(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c71"]=[{"id":"00014969","register_sub_id":"101","register_pk":"519229","name":"旧森田家住宅塀重門","kana":"きゅうもりたけじゅうたくへいじゅうもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県香南市野市町兎田字小林谷482-1他","lat":33.57317778,"lng":133.72218056,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、銅板葺、間口1.8m","structure_material":"木造","registered":"2024.03.06(令和6.03.06)","register_no":"39 - 0312","desc":"主屋の式台玄関の南東に位置し、東に広がる庭園の出入口となる門。小規模な一間一戸の棟門で、屋根は起りのある切妻造銅板葺とする。柱間の南側を板張とし、北側に片引戸を建てる。表門から主屋の式台玄関へ至る桝形状の経路に建ち、敷地景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014969"},{"id":"00014970","register_sub_id":"101","register_pk":"519230","name":"旧森田家住宅脇門","kana":"きゅうもりたけじゅうたくわきもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県香南市野市町兎田字小林谷482-1他","lat":33.57312222,"lng":133.72209444,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、間口2.0m","structure_material":"木造","registered":"2024.03.06(令和6.03.06)","register_no":"39 - 0313","desc":"敷地南面の西寄りに建つ一間一戸の薬医門。屋根は切妻造桟瓦葺とする。柱間は西側を縦板張とし、東側は引戸の格子戸を建てる。通りから主屋の内玄関へと至る門で、木柄細く全体に簡易なつくりながらも、表門、土塀とともに、屋敷南側の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014970"},{"id":"00006759","register_sub_id":"101","register_pk":"107742","name":"久保家住宅内塀","kana":"くぼけじゅうたくうちべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県安芸郡安田町大字安田1849","lat":33.4386584,"lng":133.98123458,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"石造、延長6.6m","structure_material":"石造","registered":"2007.10.02(平成19.10.02)","register_no":"39 － 0226","desc":"敷地の南西にある畑と建物との間に位置する。南北方向に延長６．６ｍ築いた石塀で、高さ１．７ｍ、上部には瓦葺屋根を置く。主に玉石を用い、竪目地をずらして交互に積み、横目地は揃え、端部に大きめの石を積む。地域的な特色のある敷地景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006759"},{"id":"00006756","register_sub_id":"101","register_pk":"107739","name":"久保家住宅蔵","kana":"くぼけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県安芸郡安田町大字安田1849","lat":33.43872108,"lng":133.98129747,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積18㎡","structure_material":"土蔵造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"39 － 0223","desc":"敷地の北辺中央に位置し、路地に接して建つ。桁行２間半、梁間２間の、土蔵造２階建で、切妻造桟瓦葺の置屋根とする。外壁は上部を土佐漆喰、腰壁を鉄板張とする。簡素な意匠でまとめるが、腰壁上の水切り瓦に地域的な特色が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006756"},{"id":"00006758","register_sub_id":"101","register_pk":"107741","name":"久保家住宅外塀","kana":"くぼけじゅうたくそとべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"高知県","address":"高知県安芸郡安田町大字安田1849","lat":33.43876618,"lng":133.98112832,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"石造、延長14m","structure_material":"石造","registered":"2007.10.02(平成19.10.02)","register_no":"39 － 0225","desc":"離れの西端から路地に沿って西方に９．９ｍ、くの字に折れて敷地西辺に３．８ｍ築く。高さ１．７ｍの石塀で、練積とし、上部には瓦葺屋根を置く。玉石や半割石を用い、目地をずらして交互に積む。イシグロと呼ばれる土佐地方特有の塀で特色ある景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006758"},{"id":"00006760","register_sub_id":"101","register_pk":"107743","name":"久保家住宅離れ","kana":"くぼけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県安芸郡安田町大字安田1849","lat":33.4387258,"lng":133.98125443,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、瓦葺、建築面積22㎡","structure_material":"木造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"39 － 0222","desc":"敷地の北辺中央に位置し、路地に接して建つ。桁行３間梁間２間の木造２階建で、切妻造桟瓦葺とする。１階はトコ付の座敷６畳とし、来客の宿泊などに使用。外壁は養生のための鉄板張で、路地側には２階のみ開口部を設ける。蔵や外塀とともに路地の景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006760"},{"id":"00006757","register_sub_id":"101","register_pk":"107740","name":"久保家住宅門","kana":"くぼけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県安芸郡安田町大字安田1849","lat":33.43857831,"lng":133.98141234,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造、瓦葺、間口1.9m","structure_material":"木造","registered":"2007.10.02(平成19.10.02)","register_no":"39 － 0224","desc":"店舗兼住宅の南側に設けられた門で、敷地南西にある畑へ繋がる庭の出入口となる。木造、切妻造、桟瓦葺で、柱心々は１．９ｍ。礎石上に土台建とし、店舗側に片引の舞良戸をたて、南半を竪板張とする。簡明な意匠の通用門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006757"},{"id":"00003725","register_sub_id":"101","register_pk":"104715","name":"公文利幸家住宅家門及び便所","kana":"くもんとしゆきけじゅうたくいえもんおよびべんじょ","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県安芸郡田野町532","lat":33.4309588,"lng":134.01405104,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋建、瓦葺、建築面積9.6㎡、門間口2.9m","structure_material":"木造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"39 － 0082","desc":"屋敷地の東南端に位置し，主屋とは渡廊下で結ばれる。桁行２間半梁間１間規模，南北棟，切妻造，桟瓦葺で，南方１間半を門とし，主屋寄りの北方１間を便所に充てる。便所は庭側と渡廊下側の両方から使える造りとする。便所と一体となった門は当地では珍しい。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003725"},{"id":"00003727","register_sub_id":"101","register_pk":"104717","name":"公文利幸家住宅蔵","kana":"くもんとしゆきけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"高知県","address":"高知県安芸郡田野町532","lat":33.43115341,"lng":134.01399733,"geo_status":"db","era":"江戸末期／昭和初期移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積16㎡","structure_material":"木造2階建","registered":"2003.12.01(平成15.12.01)","register_no":"39 － 0084","desc":"本陣・岡御殿からの移築と伝える。主屋の西方に南北棟で建つ。桁行２間梁間２間規模，切妻造，桟瓦葺の２階建蔵で，東面には下屋を差し掛け，南妻面には納屋が取り付いて蔵前を兼ねる。小規模ながら，たちの高いつくりで屋敷地内では目立った存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003727"},{"id":"00003724","register_sub_id":"101","register_pk":"104714","name":"公文利幸家住宅主屋","kana":"くもんとしゆきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県安芸郡田野町532","lat":33.43105002,"lng":134.01408261,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋建、瓦葺、建築面積64㎡","structure_material":"木造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"39 － 0081","desc":"池谷川右岸近くに位置し，道路に東妻面を見せて建つ。桁行４間梁間４間規模，東西棟，切妻造，桟瓦葺の木造平屋建で，田の字型平面をもち，南面に郷士住宅の系譜をひく式台を設ける。南北両面の下屋付け根に２段の水切瓦を付けるのも特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003724"},{"id":"00003728","register_sub_id":"101","register_pk":"104718","name":"公文利幸家住宅納屋及び離れ","kana":"くもんとしゆきけじゅうたくなやおよびはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県安芸郡田野町532","lat":33.43109854,"lng":134.01394888,"geo_status":"db","era":"大正初期／昭和初期増築","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造2階建一部平屋建、瓦葺、建築面積45㎡","structure_material":"木造2階建一部平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"39 － 0085","desc":"蔵の南方に棟を落として南北棟で建つ。桁行５間梁間２間，入母屋造，桟瓦葺の２階建納屋で，内部は南方桁行２間分に１・２階とも６畳間を設け，東面下屋の南端に３畳の離れ（お産部屋）を突き出す。納屋部下屋の付け根は水切瓦を重ねた丁寧なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003728"},{"id":"00003726","register_sub_id":"101","register_pk":"104716","name":"公文利幸家住宅渡廊下","kana":"くもんとしゆきけじゅうたくわたりろうか","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"高知県","address":"高知県安芸郡田野町532","lat":33.43099564,"lng":134.01407109,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋建、瓦葺、建築面積6.7㎡","structure_material":"木造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"39 － 0083","desc":"主屋南面の下屋庇東端から発して便所北面に取り付く長３間半の渡廊下。南北棟，両下造，桟瓦葺で，庭側の西面は腰を板壁，上部を硝子窓とし，道路側の東面は家門及び便所と同様，腰を簓子下見，上部を真壁造とする。道路沿い景観を整える要素になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003726"},{"id":"00003730","register_sub_id":"101","register_pk":"104720","name":"公文正昭家住宅蔵","kana":"くもんまさあきけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸郡田野町570-1","lat":33.43116664,"lng":134.01426686,"geo_status":"db","era":"明治29","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積67㎡","structure_material":"土蔵造2階建","registered":"2003.12.01(平成15.12.01)","register_no":"39 － 0087","desc":"主屋の西方に南北棟で建つ。北方を桁行２間梁間２間，切妻造，桟瓦葺の２階建土蔵，南方を桁行４間梁間２間，入母屋造，桟瓦葺の２階建納屋とし，納屋の１階はギャラリーとして活用されている。腰は板張，上部には土佐漆喰塗壁に２段の水切瓦を廻す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003730"},{"id":"00003729","register_sub_id":"101","register_pk":"104719","name":"公文正昭家住宅主屋","kana":"くもんまさあきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"高知県","address":"高知県安芸郡田野町570-1","lat":33.43113044,"lng":134.01435338,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積62㎡","structure_material":"木造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"39 － 0086","desc":"奈半利川に平行する池谷川右岸近くの三方が道路に囲まれた敷地に建つ。桁行４間梁間４間規模，切妻造，桟瓦葺の木造平屋建で，南面に下屋を差し掛けて玄関をとり，内部は郷士住宅の流れをひく田の字型の間取りをもつ。下屋付け根に３段重ねの水切瓦を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003729"},{"id":"00010520","register_sub_id":"101","register_pk":"199461","name":"渓鬼荘","kana":"けいきそう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"高知県","address":"高知県香美市香北町猪野々字東ヤシキ514","lat":33.706145,"lng":133.856349,"geo_status":"db","era":"昭和9／昭和39改修・平成18移築","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、茅葺、建築面積31㎡","structure_material":"木造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"39 － 0277","desc":"歌人吉井勇が高知での隠遁生活のために建てた茅葺の小庵。六畳の居間と四畳半の書斎、広縁のみで構成する簡素な建物だが、天井棹縁に丸竹、床の落掛に竹の根を使うなど風趣ある数寄屋の意匠を備える。山間部の農村における文人の草庵の静かな佇まいを残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010520"},{"id":"00006943","register_sub_id":"101","register_pk":"107925","name":"五藤家住宅板塀","kana":"ごとうけじゅうたくいたべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸市土居土居跡955","lat":33.51898314,"lng":133.91280856,"geo_status":"db","era":"明治29","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"木造、瓦葺、延長5.0m","structure_material":"木造","registered":"2008.03.07(平成20.03.07)","register_no":"39 － 0242","desc":"主屋北東隅の玄関脇から北に延び、納屋の下屋袖壁に接続する板塀で、南寄りに片引の竪舞良戸の潜りを設ける。高さ１．８ｍ、延長５．０ｍとし、目板付の竪板壁とし、頂部に瓦を載せる。主屋と納屋と連なり、上質な屋敷景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006943"},{"id":"00006938","register_sub_id":"101","register_pk":"107920","name":"五藤家住宅事務所","kana":"ごとうけじゅうたくじむしょ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"高知県","address":"高知県安芸市土居土居跡955","lat":33.51889962,"lng":133.91290077,"geo_status":"db","era":"昭和24","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積17㎡","structure_material":"木造平屋建","registered":"2008.03.07(平成20.03.07)","register_no":"39 － 0237","desc":"敷地の東側に建つ面積１７㎡の木造平屋建の事務所。北面に出入口を設け、東面は竪羽目板張で格子付窓を設け、南・西面は腰板壁で大きくガラス窓を開ける。小壁は土佐漆喰仕上げ。小規模ながら、わずかに起る入母屋屋根が印象的である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006938"},{"id":"00006937","register_sub_id":"101","register_pk":"107919","name":"五藤家住宅主屋","kana":"ごとうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸市土居土居跡955","lat":33.51891776,"lng":133.91274935,"geo_status":"db","era":"明治29","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積109㎡","structure_material":"木造平屋建","registered":"2008.03.07(平成20.03.07)","register_no":"39 － 0236","desc":"安芸城跡城山の麓、堀の内側に占める屋敷地のほぼ中央に東西棟で建つ。桁行６間半梁間３間半規模、寄棟造桟瓦葺の上屋に、四周に下屋を付け、北西隅に東西棟切妻造の釜屋を張り出す。右瓦と左瓦を葺き分けるなど土佐の伝統を踏襲する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006937"},{"id":"00006941","register_sub_id":"101","register_pk":"107923","name":"五藤家住宅納屋","kana":"ごとうけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和中","pref":"高知県","address":"高知県安芸市土居土居跡955","lat":33.51903316,"lng":133.91276125,"geo_status":"db","era":"昭和24","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造2階建、瓦葺、建築面積27㎡","structure_material":"木造2階建","registered":"2008.03.07(平成20.03.07)","register_no":"39 － 0240","desc":"主屋の北側に中庭を挟んで建つ。桁行４間梁間２間、切妻造桟瓦葺、木造２階建の東西棟である。南面に桟瓦葺の庇をつける。外壁は竪羽目板張で、西妻面上部及び南面上部は土佐漆喰仕上げとする。内部は中央で東西２室に間仕切り、それぞれに階段を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006941"},{"id":"00006939","register_sub_id":"101","register_pk":"107921","name":"五藤家住宅離れ","kana":"ごとうけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸市土居土居跡955","lat":33.5188989,"lng":133.91251776,"geo_status":"db","era":"明治29","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積25㎡","structure_material":"木造平屋建","registered":"2008.03.07(平成20.03.07)","register_no":"39 － 0238","desc":"主屋の西側に建つ木造平屋建。東西棟の寄棟造桟瓦葺で、南北に半間の下屋庇を付ける。西面と南面は右瓦葺、東面と北面を左瓦葺とするなど葺き分ける、土佐の伝統的な仕様を残す。平面はトコと棚をもつ６畳と次の間４畳半からなり、南面に縁を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006939"},{"id":"00006940","register_sub_id":"101","register_pk":"107922","name":"五藤家住宅付属屋","kana":"ごとうけじゅうたくふぞくや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"高知県","address":"高知県安芸市土居土居跡955","lat":33.51903832,"lng":133.91262252,"geo_status":"db","era":"昭和29","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積40㎡","structure_material":"木造平屋建","registered":"2008.03.07(平成20.03.07)","register_no":"39 － 0239","desc":"主屋釜屋の北方に東西棟で建つ木造平屋建。切妻造桟瓦葺で、西側に便所と台所がそれぞれ棟を違えて付く。平面は４畳半間と３畳間が東西に並び、南側には濡縁を設け、北面は黒色塗装の竪羽目板張とし、出窓を付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006940"},{"id":"00006942","register_sub_id":"101","register_pk":"107924","name":"五藤家住宅物置","kana":"ごとうけじゅうたくものおき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"高知県","address":"高知県安芸市土居土居跡955","lat":33.51903554,"lng":133.91269225,"geo_status":"db","era":"明治29","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積8.3㎡","structure_material":"木造平屋建","registered":"2008.03.07(平成20.03.07)","register_no":"39 － 0241","desc":"敷地の北側、付属屋と納屋の間に建つ。桁行２間梁間１間規模の木造平屋建。東西棟とし、桟瓦葺の招屋根とする。南面は、西寄りに板壁を設け、開口には建具をたてず、開放とする。北面外壁は竪板壁とし、板塀状に造り、敷地周囲の景観と調和を図る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006942"},{"id":"00004447","register_sub_id":"101","register_pk":"105437","name":"齋藤家住宅勝手門及び塀","kana":"さいとうけじゅうたくかってもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県土佐市宇佐町宇佐字渭浜260","lat":33.44475096,"lng":133.4329189,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"煉瓦造、瓦葺、延長4.5m","structure_material":"煉瓦造","registered":"2004.11.08(平成16.11.08)","register_no":"39 － 0161","desc":"主屋西南端，玄関脇に発し西外塀に突き当たる塀で，玄関前庭と台所前裏庭方面とを区画する。庭塀と同様，自然石の石積基礎の上に築かれた，煉瓦１枚半厚，イギリス積の煉瓦塀で，小屋根には左瓦を用いる。玄関寄りを一段高くし櫛形アーチの勝手門を開ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004447"},{"id":"00004444","register_sub_id":"101","register_pk":"105434","name":"齋藤家住宅蔵","kana":"さいとうけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県土佐市宇佐町宇佐2５９－１","lat":33.44488014,"lng":133.43268493,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積38㎡","structure_material":"土蔵造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"39 － 0158","desc":"屋敷地の北西隅に位置し，石積基礎の上に東西棟で建つ。切妻造，桟瓦葺，置屋根式の２階建土蔵で，桁行３間半梁間２間半の規模。南面東寄りに土庇を差し掛け，戸口前に石階段を設ける。外壁は土佐漆喰塗とし，土佐特有の水切瓦を３段廻している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004444"},{"id":"00004443","register_sub_id":"101","register_pk":"105433","name":"齋藤家住宅主屋","kana":"さいとうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"高知県","address":"高知県土佐市宇佐町宇佐字渭浜260","lat":33.44483706,"lng":133.43291933,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積128㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"39 － 0157","desc":"南北に長い屋敷地のやや南寄りに東西棟で建つ。桁行６間梁間４間半規模，入母屋造，桟瓦葺の木造平屋建で，東面を除く３面に下屋を廻す。南側に西から式台玄関，４畳半，４畳中の間，床付６畳座敷の４室を配する。南面縁側の柱の自然木風に見せた造作に特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004443"},{"id":"00004448","register_sub_id":"101","register_pk":"105438","name":"齋藤家住宅外塀","kana":"さいとうけじゅうたくそとべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"高知県","address":"高知県土佐市宇佐町宇佐字渭浜260","lat":33.44474494,"lng":133.43288247,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、延長37m","structure_material":"木造","registered":"2004.11.08(平成16.11.08)","register_no":"39 － 0162","desc":"長屋門の東及び西から北に折れて屋敷地の南及び西辺を画し，西辺北方には通用門を開ける。亀甲積石垣を基礎として建つ真壁造の塀で，腰を押縁下見板張，上部を漆喰塗とし，柱から腕木を出して桟瓦葺の小屋根を受ける。屋敷地外構に欠くことのできない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004448"},{"id":"00004445","register_sub_id":"101","register_pk":"105435","name":"齋藤家住宅長屋門","kana":"さいとうけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"高知県","address":"高知県土佐市宇佐町宇佐字渭浜260","lat":33.44476221,"lng":133.4330239,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積29㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"39 － 0159","desc":"屋敷地南辺の西寄りに東西棟で建つ。桁行５間梁間１間半規模，入母屋造，桟瓦葺の長屋門で，門口の西側を土間付き３畳，東側２間分を作業場とする。屋敷地西辺から南辺に廻した亀甲積石垣を基礎として建ち，外塀とともに屋敷正面の構えの中心的要素になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004445"},{"id":"00004446","register_sub_id":"101","register_pk":"105436","name":"齋藤家住宅庭門及び塀","kana":"さいとうけじゅうたくにわもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県土佐市宇佐町宇佐字渭浜260","lat":33.44478476,"lng":133.43299763,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造、瓦葺、間口0.90m、塀 煉瓦造、延長5.3m","structure_material":"木造","registered":"2004.11.08(平成16.11.08)","register_no":"39 － 0160","desc":"庭門は主屋玄関と４畳半との室境の南に位置し，南北棟，桟瓦葺の切妻屋根には緩い起りをつける。庭門南端に発し，中途で東南方に折れて長屋門の東北端に取り付く庭塀は，石積基礎の上に築かれた煉瓦塀で，桟瓦葺の小屋根を戴き，玄関前庭空間の主要素になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004446"},{"id":"00003731","register_sub_id":"101","register_pk":"104721","name":"佐野家住宅主屋","kana":"さのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"高知県","address":"高知県安芸郡田野町1305","lat":33.4324461,"lng":134.00999801,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積115㎡","structure_material":"木造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"39 － 0088","desc":"藩校跡西南方に位置する。桁行６間梁間４間半規模，入母屋造，桟瓦葺の木造平屋建で，南面中央に式台玄関を設け，東側に３畳・４畳・床付６畳を並べ，東面と南面に縁廊下を廻す。安政２年（１８５５）の祈祷札を持つ土佐郷士住宅の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003731"},{"id":"00004453","register_sub_id":"101","register_pk":"105443","name":"澤村家住宅蔵","kana":"さわむらけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"高知県","address":"高知県土佐市高岡町甲506-2","lat":33.49141585,"lng":133.43833851,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積26㎡","structure_material":"土蔵造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"39 － 0167","desc":"屋敷地の東南隅部に南北棟で建つ。桁行２間半梁間２間規模，切妻造，桟瓦葺，置屋根式の２階建土蔵で，西面に下屋を差し掛け，その南寄りを３畳大の番屋に充てる。外部は腰を押縁下見板張，上部を土佐漆喰塗とし，４段の水切瓦を廻した丁寧なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004453"},{"id":"00004452","register_sub_id":"101","register_pk":"105442","name":"澤村家住宅主屋","kana":"さわむらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"高知県","address":"高知県土佐市高岡町甲506-2","lat":33.49154834,"lng":133.43819965,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積175㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"39 － 0166","desc":"桁行９間梁間４間半規模で，入母屋造，桟瓦葺の当地における伝統的な和風住宅の床上部とかま屋部との間に，フランス瓦葺の急傾斜切妻屋根をもつ洋館を交差させた特異な形態をとる。アメリカ移民経験者により洋風生活様式が採り入れられた住宅遺構として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004452"},{"id":"00004454","register_sub_id":"101","register_pk":"105444","name":"澤村家住宅便所","kana":"さわむらけじゅうたくべんじょ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"高知県","address":"高知県土佐市高岡町甲506-2","lat":33.49161294,"lng":133.43810368,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積4.3㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"39 － 0168","desc":"敷地の北西隅部に位置し，西外塀に沿って南北棟で建つ。平面規模桁行３．３２ｍ梁行１．３ｍの木造平屋建で，桟瓦葺の切妻屋根を架ける。東面に４つの開口部を設け，北端を汲み取り口とする。腰を縦板張，上部を土佐漆喰塗で仕上げ，西面に扇形の窓を穿つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004454"},{"id":"00004455","register_sub_id":"101","register_pk":"105445","name":"澤村家住宅門","kana":"さわむらけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"高知県","address":"高知県土佐市高岡町甲506-2","lat":33.49136504,"lng":133.43822839,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄筋コンクリート造、間口4.0m","structure_material":"鉄筋コンクリート造","registered":"2004.11.08(平成16.11.08)","register_no":"39 － 0169","desc":"主屋玄関の南方，蔵の西南に位置する。間口２．７ｍで鉄筋コンクリート造門柱を建て鉄扉を吊り，東にひとまわり小さな門柱を建て脇門とする。門柱は側面頂部をアーチ形とし，内側に１段，外側に２段の凸面を付けた洋風の門で，主屋洋館に対応した意匠をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004455"},{"id":"00004461","register_sub_id":"101","register_pk":"105451","name":"塩田家住宅主屋","kana":"しおたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"高知県","address":"高知県土佐市高岡町乙150","lat":33.49680007,"lng":133.42239784,"geo_status":"db","era":"昭和20","year":1945,"year_source":"db","year_min":1945,"year_max":1945,"year_label":null,"structure":"木造2階建、瓦葺、建築面積86㎡","structure_material":"木造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"39 － 0175","desc":"街道に南面する敷地の南寄りに東西棟で建つ。間口４間，切妻造，桟瓦葺の木造２階建住宅で，背後に南北棟の平屋建を付属する。正面東寄りに入母屋造の玄関を設け，２階には土佐漆喰塗壁に１段の水切瓦を付ける。正面両端に袖卯建を出しているのが特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004461"},{"id":"00002862","register_sub_id":"101","register_pk":"103852","name":"島内克之家住宅内塀","kana":"しまのうちかつゆきけじゅうたくうちべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県香南市野市町上岡2621","lat":33.5567646,"lng":133.68580633,"geo_status":"db","era":"明治44","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"土塀、瓦葺、総延長14m及び石造、延長6.4m","structure_material":"土塀","registered":"2002.06.25(平成14.06.25)","register_no":"39 － 0053","desc":"主屋と長屋門との間に築造された東西棟の小屋根付き土塀と，その東端から北方へ延びるイシグロ風の石積塀から成る。主屋南方の庭園と長屋門北方の作業庭及び屋敷地東方の畑を区画する内塀で，庭園側の入隅は築山の擁壁を兼ねたつくりとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002862"},{"id":"00002863","register_sub_id":"101","register_pk":"103853","name":"島内克之家住宅汲池","kana":"しまのうちかつゆきけじゅうたくくみち","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"高知県","address":"高知県香南市野市町上岡2621","lat":33.55672825,"lng":133.68581025,"geo_status":"db","era":"明治44","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"石造、面積2.3㎡","structure_material":"石造","registered":"2002.06.25(平成14.06.25)","register_no":"39 － 0054","desc":"長屋門北東端から北に延びる土塀の北端西側に位置する。屋敷地南辺沿いを流れる水路から引水し，長屋門東面沿いから土塀下を通して導水する。汲池は自然石で組まれた１．５ｍ四方の小さな池であるが，当地方の用水利用の一端を窺い知るうえで貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002863"},{"id":"00002858","register_sub_id":"101","register_pk":"103848","name":"島内克之家住宅蔵","kana":"しまのうちかつゆきけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県香南市野市町上岡2621","lat":33.55688883,"lng":133.68565921,"geo_status":"db","era":"明治44","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積18㎡","structure_material":"土蔵造2階建","registered":"2002.06.25(平成14.06.25)","register_no":"39 － 0049","desc":"主屋の西方に南北棟で建つ。桁行２間半，梁間２間規模，置屋根形式の切妻造，桟瓦葺の２階建妻入土蔵で，外観は腰を簓子下見，上部を土佐漆喰塗とし，西面は２段，北妻面には３段の水切瓦を付けるなど土佐における土蔵建築の特徴をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002858"},{"id":"00002857","register_sub_id":"101","register_pk":"103847","name":"島内克之家住宅主屋","kana":"しまのうちかつゆきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"高知県","address":"高知県香南市野市町上岡2621","lat":33.55686846,"lng":133.68575771,"geo_status":"db","era":"嘉永3頃／明治期増築","year":1850,"year_source":"db","year_min":1850,"year_max":1850,"year_label":null,"structure":"木造2階建、瓦葺、建築面積135㎡","structure_material":"木造2階建","registered":"2002.06.25(平成14.06.25)","register_no":"39 － 0048","desc":"字神母屋敷の東北隅近くに屋敷地を構える。主屋は桁行５間半，梁間６間規模の東西棟，桟瓦葺，入母屋造で，梁行が長い６間取に特徴があり，南東北の３面に錣庇を廻す。後に西寄りに南北棟，入母屋造の２階を増築して土佐でいうトンボ造りの構成をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002857"},{"id":"00002861","register_sub_id":"101","register_pk":"103851","name":"島内克之家住宅外塀","kana":"しまのうちかつゆきけじゅうたくそとべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県香南市野市町上岡2621","lat":33.55661066,"lng":133.68584522,"geo_status":"db","era":"明治44","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"土塀、瓦葺、延長6.5m","structure_material":"土塀","registered":"2002.06.25(平成14.06.25)","register_no":"39 － 0052","desc":"長屋門東南端に発して屋敷地東辺に回り込む折れ曲がり延長６．５ｍほどの塀。腰高く自然石を亀甲状に積み，上部を土佐漆喰塗の土塀とし桟瓦葺の小屋根を架ける。長屋門西方の下見板塀とは対照をなし，屋敷構えの正面部を整える役割を果たしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002861"},{"id":"00002860","register_sub_id":"101","register_pk":"103850","name":"島内克之家住宅長屋門","kana":"しまのうちかつゆきけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県香南市野市町上岡2621","lat":33.55665846,"lng":133.68580013,"geo_status":"db","era":"明治44","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積64㎡、板塀付","structure_material":"木造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"39 － 0051","desc":"屋敷地西辺沿いから東方に回り込んでくる水路から北方にひいた位置に建つ。桁行６間半，梁間２間半規模の東西棟，桟瓦葺，入母屋造で，正面右に両開き戸と通用口を開け，横壁に土佐漆喰で紗綾文様を描く。たちの高い大型の長屋門になり当家の格をも示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002860"},{"id":"00002859","register_sub_id":"101","register_pk":"103849","name":"島内克之家住宅納屋及び蚕室","kana":"しまのうちかつゆきけじゅうたくなやおよびさんしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県香南市野市町上岡2621","lat":33.55676579,"lng":133.68565033,"geo_status":"db","era":"明治44","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造2階建、瓦葺、建築面積88㎡","structure_material":"木造2階建","registered":"2002.06.25(平成14.06.25)","register_no":"39 － 0050","desc":"主屋の西南方，蔵の南方に南北棟で建つ。桁行１１間，梁間２間規模で，北方桁行６間を２階建蚕室とし，南方は平屋建の納屋とし東面庭側に屋根を葺き下ろす。西面は腰を簓子下見，上部を真壁造として蔵とともに屋敷地西辺水路沿いの景観に趣をあたえている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002859"},{"id":"00002855","register_sub_id":"101","register_pk":"103845","name":"島内章子家住宅家門","kana":"しまのうちゆきこけじゅうたくいえもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"高知県","address":"高知県香南市野市町上岡2604","lat":33.55650034,"lng":133.68487982,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造薬医門、瓦葺、間口2.0m","structure_material":"木造薬医門","registered":"2002.06.25(平成14.06.25)","register_no":"39 － 0046","desc":"屋敷地の東南隅部に位置し，南側前面道路から鍵形に階段を昇った地点に南北棟で建つ。１間１戸，桟瓦葺，切妻造の薬医門で，緩やかな起りを付けた南妻面を道路側に見せる。主屋玄関部と居間棟の入母屋とともに屋敷構えの南立面を構成する主要素になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002855"},{"id":"00002856","register_sub_id":"101","register_pk":"103846","name":"島内章子家住宅石垣","kana":"しまのうちゆきこけじゅうたくいしがき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"高知県","address":"高知県香南市野市町上岡2604","lat":33.55652714,"lng":133.68476403,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"石造、延長25m","structure_material":"石造","registered":"2002.06.25(平成14.06.25)","register_no":"39 － 0047","desc":"屋敷地南辺から西側通路沿いに折れ曲がり築かれる。自然石の巨石を積んだ石積擁壁で，頂部に低い鉄筋コンクリート塀を廻す。東端部は家門へのアプローチ階段の高欄を兼ねており，渦巻をモチーフとした特異な意匠と風呂に共通する装飾が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002856"},{"id":"00002852","register_sub_id":"101","register_pk":"103842","name":"島内章子家住宅蔵","kana":"しまのうちゆきこけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"高知県","address":"高知県香南市野市町上岡2604","lat":33.55675352,"lng":133.6848385,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積31㎡","structure_material":"土蔵造2階建","registered":"2002.06.25(平成14.06.25)","register_no":"39 － 0043","desc":"主屋かま屋の北方，脇離れの西方，屋敷地西側通路に沿って南北棟で建つ。桁行４間，梁間２間規模の切妻造，２階建土蔵で，１階の内部は２室に分け南室は南妻面に，北室は東面に出入口を設ける。外観は腰を簓子下見，上部を土佐漆喰塗とし水切瓦を付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002852"},{"id":"00002850","register_sub_id":"101","register_pk":"103840","name":"島内章子家住宅主屋","kana":"しまのうちゆきこけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"高知県","address":"高知県香南市野市町上岡2604","lat":33.55660577,"lng":133.68486592,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、瓦葺、建築面積130㎡","structure_material":"木造2階建","registered":"2002.06.25(平成14.06.25)","register_no":"39 － 0041","desc":"字執行屋敷の東に隣接する字神母屋敷のほぼ中央に南北に長い屋敷地を構える。主屋は東西棟，入母屋造，平屋建の玄関客間棟，南北棟，入母屋造，２階建の居間棟と東西棟，寄棟造のかま屋棟から成り，棟を直交させた構成は当地に見られるトンボ造りを継承する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002850"},{"id":"00002853","register_sub_id":"101","register_pk":"103843","name":"島内章子家住宅納屋","kana":"しまのうちゆきこけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"江戸","pref":"高知県","address":"高知県香南市野市町上岡2604","lat":33.55687028,"lng":133.68486722,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積88㎡","structure_material":"木造2階建","registered":"2002.06.25(平成14.06.25)","register_no":"39 － 0044","desc":"蔵の北に接して南北棟で建つ。桁行８間，梁間３間規模，切妻造，桟瓦葺の平屋建で，畑側の東面は１間半幅の下屋を付けた形態をとる。通路側西面の外観は長屋門風で，出入口の横壁に紗綾形文様をつくり，屋根は出桁造により軒出を深くしている点に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002853"},{"id":"00002854","register_sub_id":"101","register_pk":"103844","name":"島内章子家住宅風呂","kana":"しまのうちゆきこけじゅうたくふろ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"高知県","address":"高知県香南市野市町上岡2604","lat":33.55671274,"lng":133.68494507,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積8.8㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"39 － 0045","desc":"主屋の北方，脇離れの東に接して建つ。２．２ｍ×４ｍの平面規模で，内部は南北２室に分け，北側を浴室とする。鉄筋コンクリート造，平屋建，陸屋根造で，浴室部にはパラペットを立ち上げて装飾を廻す。高知における初期鉄筋コンクリート造住宅遺構のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002854"},{"id":"00002851","register_sub_id":"101","register_pk":"103841","name":"島内章子家住宅脇離れ","kana":"しまのうちゆきこけじゅうたくわきはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"江戸","pref":"高知県","address":"高知県香南市野市町上岡2604","lat":33.556755,"lng":133.68492923,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積33㎡","structure_material":"木造2階建","registered":"2002.06.25(平成14.06.25)","register_no":"39 － 0042","desc":"屋敷地のほぼ中央，主屋の北方に位置し，蔵の東面に接して東西棟で建つ。桁行４間，梁間３間規模の桟瓦葺，切妻造２階建で，１階は裏の畑への通り庭と外便所を兼ね，２階には座敷を設ける。土佐中部の郷士住居における離れ屋の形式を伝えるものとして貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002851"},{"id":"00001354","register_sub_id":"101","register_pk":"102344","name":"末延家住宅（旧末延堂医院）かま屋","kana":"すえのぶけじゅうたく（きゅうすえのぶどういいん）かまや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"高知県","address":"高知県安芸郡芸西村和食甲1586-1","lat":33.52027422,"lng":133.81022232,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積40㎡","structure_material":"木造平屋建","registered":"1999.10.14(平成11.10.14)","register_no":"39 － 0005","desc":"主屋の北側に敷地境に沿って建つ。桁行７間，梁間１間半の細長い建屋で，東側を３室の使用人用居室，西端２間分を釜屋に充てる。北面は連子窓の上部に小庇を付け，屋根は西寄りを１段高くし，さらに釜屋部分に換気抜きの小屋根を架けて変化をもたせている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001354"},{"id":"00001353","register_sub_id":"101","register_pk":"102343","name":"末延家住宅（旧末延堂医院）蔵","kana":"すえのぶけじゅうたく（きゅうすえのぶどういいん）くら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"高知県","address":"高知県安芸郡芸西村和食甲1586-1","lat":33.52026715,"lng":133.81013514,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"1999.10.14(平成11.10.14)","register_no":"39 － 0004","desc":"敷地の西北端に建つ東西棟，瓦葺切妻屋根，平入の２階建土蔵。内部は１室構成で，２階北面に小窓を開けただけの閉鎖的なつくりとなる。北面は水切り瓦を３段に付けた意匠で，屋敷構えの北面の景観を端部でまとめあげる役割を果たしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001353"},{"id":"00001355","register_sub_id":"101","register_pk":"102345","name":"末延家住宅（旧末延堂医院）長屋門","kana":"すえのぶけじゅうたく（きゅうすえのぶどういいん）ながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"高知県","address":"高知県安芸郡芸西村和食甲1586-1","lat":33.52023222,"lng":133.81032997,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積35㎡","structure_material":"木造平屋建","registered":"1999.10.14(平成11.10.14)","register_no":"39 － 0006","desc":"和食地区を南北に貫く県道羽尾琴浜線に沿って東面して建つ。木造平屋建，瓦葺寄棟屋根，南北棟の長屋門で，正面中央に門を開き，主屋の居住用玄関に通じる。長屋門の北にはかま屋と意匠をあわせた屋根塀を，南には診療所用の門に連なるコンクリート塀を付す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001355"},{"id":"00006270","register_sub_id":"101","register_pk":"107254","name":"杉本家住宅石垣","kana":"すぎもとけじゅうたくいしがき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸市本町2-4-3","lat":33.49921577,"lng":133.90650622,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"石造、総延長21m、石段付","structure_material":"石造","registered":"2007.07.31(平成19.07.31)","register_no":"39 － 0211","desc":"客間棟南側にある庭の南辺及び西辺の位置に，丸石を垂直に積み，南側一部を傾斜を付けて積む。延長２１ｍとし，高い所では１．２ｍの高さとする。それぞれの一部に石段を設ける。敷地内を高低差のある空間とし，変化のある敷地内景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006270"},{"id":"00006267","register_sub_id":"101","register_pk":"107251","name":"杉本家住宅客間棟","kana":"すぎもとけじゅうたくきゃくまとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"高知県","address":"高知県安芸市本町2-4-3","lat":33.49949425,"lng":133.90663794,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積83㎡","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"39 － 0209","desc":"北側道路からやや奥まった位置に建つ。桁行４間，梁間４間半の規模で，木造平屋建，切妻造，桟瓦葺とする。北西隅を式台玄関とし，東側に南北に１０畳間及び９畳半の座敷を並べる。南と東に畳廊下及び切目縁を廻す。西側漆喰壁に６段の水切り瓦を並べる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006267"},{"id":"00006271","register_sub_id":"101","register_pk":"107255","name":"杉本家住宅塀","kana":"すぎもとけじゅうたくへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸市本町2-4-3","lat":33.49933284,"lng":133.90667377,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"練塀、瓦葺、延長17m","structure_material":"練塀","registered":"2007.07.31(平成19.07.31)","register_no":"39 － 0210","desc":"敷地東辺に沿って築かれた瓦積の練塀で，延長１７ｍ，高さ２．８ｍ，幅０．６ｍの規模で，客間棟客座敷及び庭の東側を囲い目隠しとしている。石積の上に密に瓦を積み，瓦屋根を載せる。敷地境になる東面は漆喰塗とする。重みのある敷地外観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006271"},{"id":"00003756","register_sub_id":"101","register_pk":"104746","name":"隅田家住宅便所及び納屋","kana":"すみだけじゅうたくべんじょおよびなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県安芸郡田野町2363-1","lat":33.42711804,"lng":134.00353087,"geo_status":"db","era":"大正15頃","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積24㎡","structure_material":"木造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"39 － 0113","desc":"主屋北西端から釜屋と平行して北方に延びた建屋。桁行６間梁間１間規模の細長の平面を有し，南方３間分を便所・風呂，北方３間分を納屋，北端半間分を外便所に充てる。屋根は，切妻造，桟瓦葺とし，納屋の東面側は出桁造として屋根を葺き下ろす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003756"},{"id":"00001968","register_sub_id":"101","register_pk":"102958","name":"竹崎家住宅（旧高田屋）離れ","kana":"たけざきけじゅうたく（きゅうたかだや）はなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸郡奈半利町乙1699","lat":33.42476383,"lng":134.02173744,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積25㎡","structure_material":"木造平屋建","registered":"2000.10.18(平成12.10.18)","register_no":"39 － 0018","desc":"主屋の東方に建つ。桁行３間，梁行２間規模，南北棟，寄棟造，桟瓦葺の木造２階建で，１階は物置として階高を低く押さえた造りとし，２階は床付きの６畳間とする。外壁は，真壁造で，腰を押縁下見とし，南面は気候風土に配慮して板張とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001968"},{"id":"00012250","register_sub_id":"101","register_pk":"353051","name":"竹村家土蔵","kana":"たけむらけどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県高岡郡佐川町字東町甲1285","lat":33.498976,"lng":133.290126,"geo_status":"db","era":"明治後期／平成12年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積63㎡","structure_material":"土蔵造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"39-294","desc":"佐川町中心部に建つ。切妻造二階建、桟瓦葺で、平入の西面に下屋が付き、妻面に三段、背面に二段の水切瓦を設け、外壁は軒まで塗込める。内部は一、二階とも板敷二室とし、それぞれに入口を設ける。地域の特色をよく示す外観を持つ比較的大規模な土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012250"},{"id":"00003739","register_sub_id":"101","register_pk":"104729","name":"谷豊家住宅離れ","kana":"たにゆたかけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"江戸","pref":"高知県","address":"高知県安芸郡田野町1933","lat":33.42827643,"lng":134.01082826,"geo_status":"db","era":"江戸末期／昭和6移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積154㎡","structure_material":"木造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"39 － 0096","desc":"主屋の北方に南北棟で建つ。入母屋造，桟瓦葺で，南面に２重の妻を見せるのが特徴。桁行５間半梁間４間半規模，内部は西南の床付き１０畳座敷，東南の書院付き８畳座敷など７室から成り，４周に４尺幅の縁廊下を廻す。奈半利の旧家主屋を移築したとされる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003739"},{"id":"00003740","register_sub_id":"101","register_pk":"104730","name":"谷豊家住宅便所","kana":"たにゆたかけじゅうたくべんじょ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"高知県","address":"高知県安芸郡田野町1933","lat":33.42828463,"lng":134.0107839,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積7.0㎡","structure_material":"木造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"39 － 0097","desc":"主屋の北方，離れの南方，屋敷地東辺沿いに建ち，渡廊下で離れと結ばれる。東西棟の入母屋造，桟瓦葺で，規模は桁行１間半梁間１間半とする。外部腰を簓子下見，上部を漆喰塗の真壁造とし，丸窓や建具などの数寄屋風意匠で瀟洒な外観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003740"},{"id":"00012846","register_sub_id":"101","register_pk":"367749","name":"津田家住宅主屋","kana":"つだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県安芸市土居字西木戸838他","lat":33.52080778,"lng":133.90622583,"geo_status":"db","era":"大正3年頃","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積144㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"39 － 0300","desc":"土居廓中西側の旧武家地にある。主屋は敷地東北隅に南面して建つ切妻造桟瓦葺妻入の平屋建で、西面北半に寄棟造の座敷棟を出し、四周に下屋を廻す。内部は田字形平面で、南面西端を玄関、街路沿いの東端を土間とする。武家地の景観を継承する近代の和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012846"},{"id":"00012847","register_sub_id":"101","register_pk":"367750","name":"津田家住宅附属屋","kana":"つだけじゅうたくふぞくや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"高知県","address":"高知県安芸市土居字西木戸838他","lat":33.52080778,"lng":133.90622583,"geo_status":"db","era":"大正3年頃／昭和50年代改修","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積34㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"39 － 0301","desc":"敷地東南隅にあり、主屋南面東端に接続して建つ。東西棟の平屋建、切妻造桟瓦葺、基礎切石積。外壁は縦板張で小壁を漆喰塗とし、南面中央に高窓を設ける。内部はもと一室で、診療室に利用した。街路沿いの角地にあって旧武家町の歴史的景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012847"},{"id":"00012848","register_sub_id":"101","register_pk":"367751","name":"津田家住宅門及び塀","kana":"つだけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県安芸市土居字西木戸838他","lat":33.52080778,"lng":133.90622583,"geo_status":"db","era":"大正3年頃","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"門 木造、瓦葺、間口3.0m 塀 練塀、瓦葺、延長5.5m","structure_material":"門 木造","registered":"2019.03.29(平成31.03.29)","register_no":"39 － 0302","desc":"敷地南面の路地沿いに建つ。塀は瓦を密に用いた練塀で、基礎は自然石積、屋根は桟瓦葺とする。門は塀東端に開き、東側を附属屋と接続する切妻造桟瓦葺の棟門で、冠木上に渡した三本の腕木で軒桁を受ける。武士住宅を思わせる、風格ある表構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012848"},{"id":"00004839","register_sub_id":"101","register_pk":"105829","name":"寺村徳夫家住宅蔵","kana":"てらむらのりおけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸市土居993-1","lat":33.51825718,"lng":133.9114411,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積22㎡、木戸門付","structure_material":"土蔵造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"39 － 0185","desc":"屋敷地北西隅部に位置し，切石積基礎上に南北棟で建つ。桁行３間梁間２間規模，切妻造，桟瓦葺，平入の２階建土蔵で，東面に下屋を差し掛けて戸口を設ける。外部は腰を縦板張，上部は軒裏まで土佐漆喰塗とし，２段の水切瓦を廻した土佐特有の土蔵のつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004839"},{"id":"00004838","register_sub_id":"101","register_pk":"105828","name":"寺村徳夫家住宅長屋門","kana":"てらむらのりおけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸市土居993-1","lat":33.51795741,"lng":133.91150145,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積51㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"39 － 0184","desc":"屋敷地西南角に位置し，切石積基礎上に東西棟で建つ。桁行７間１尺梁行２間，切妻造，桟瓦葺の平屋建で，東端に門口をとり，西側に４畳半４室を東西に並べ，北面に廊下を設ける。外部は腰押縁下見板張，上部土佐漆喰塗。正面の構えに欠くことのできない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004838"},{"id":"00004840","register_sub_id":"101","register_pk":"105830","name":"寺村徳夫家住宅離れ","kana":"てらむらのりおけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸市土居993-1","lat":33.51825791,"lng":133.91150693,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積25㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"39 － 0186","desc":"蔵の東に接して東西棟で建つ。切妻造，桟瓦葺の木造平屋建で，桁行４間半梁行２間半の平面規模を有する。内部は東方を土間，西方を床上部とし，外部北面は真壁造で，腰に縦板を張り，南面の土間庇は井戸を覆う。主屋背後，屋敷地北部を構成する要素のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004840"},{"id":"00004841","register_sub_id":"101","register_pk":"105831","name":"寺村徳夫家住宅塀","kana":"てらむらのりおけじゅうたくへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸市土居993-1","lat":33.5181013,"lng":133.91142003,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土塀、瓦葺、延長23m","structure_material":"土塀","registered":"2005.07.12(平成17.07.12)","register_no":"39 － 0187","desc":"屋敷地西辺を画する外塀で，長屋門北西端に発する南部１０ｍ分を土佐漆喰塗の高さ１．７ｍの土塀とし，蔵附属の木戸門から南１３ｍ分の北部を石練塀とする。石練塀は，乱積石積基礎上に建ち，両端部を古瓦積，その間を川原石の練積とした特色ある造りになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004841"},{"id":"00006347","register_sub_id":"101","register_pk":"107330","name":"西岡家住宅蔵","kana":"にしおかけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸郡安田町大字安田1807","lat":33.43793756,"lng":133.98105267,"geo_status":"db","era":"明治20頃","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造2階建、瓦葺、建築面積17㎡","structure_material":"木造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"39 － 0219","desc":"離れの北側、敷地北側の通りに接して建つ。桁行２間半、梁間２間、土蔵造２階建、切妻造、桟瓦葺。置屋根とし、鉢巻を付ける。東面に片開の出入口を設け、庇を付ける。妻側が通りに接し、２段に並べた水切り瓦が、土佐地方独特の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006347"},{"id":"00006345","register_sub_id":"101","register_pk":"107328","name":"西岡家住宅主屋","kana":"にしおかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸郡安田町大字安田1807","lat":33.4377392,"lng":133.98107719,"geo_status":"db","era":"明治20頃","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積66㎡","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"39 － 0217","desc":"道路から前庭を介して東面して建つ。木造平屋建、桟瓦葺で、和室２室から成り、西方に便所・風呂が付属。寄棟と入母屋の屋根を重ねた主体部に、入母屋屋根の玄関や下屋庇が付き、複雑な屋根を構成する。外壁は土佐漆喰で、玄関の黒壁がアクセントとなる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006345"},{"id":"00006346","register_sub_id":"101","register_pk":"107329","name":"西岡家住宅離れ","kana":"にしおかけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和中","pref":"高知県","address":"高知県安芸郡安田町大字安田1807","lat":33.43786531,"lng":133.98102729,"geo_status":"db","era":"昭和28頃","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造2階建、瓦葺、建築面積44㎡","structure_material":"木造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"39 － 0218","desc":"主屋の後方、敷地西端に位置する。桁行４間半、梁間２間半、木造２階建、切妻造、桟瓦葺。１階は和室２室、２階は客用の座敷２室を並べる。棟が高く大きな妻面を形成し、破風板などを塗り込め、水切り瓦を見せる。重厚かつ地域的な特色のある外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006346"},{"id":"00006349","register_sub_id":"101","register_pk":"107332","name":"西岡家住宅門及び塀","kana":"にしおかけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"高知県","address":"高知県安芸郡安田町大字安田1807","lat":33.43775224,"lng":133.98113025,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"門 鉄筋コンクリート造門柱2基、間口2.0m、塀 鉄筋コンクリート造、延長7.0m","structure_material":"門 鉄筋コンクリート造門柱2基","registered":"2007.10.02(平成19.10.02)","register_no":"39 － 0220","desc":"主屋の前方に位置する鉄筋コンクリート造の門と塀。前面道路からやや奥まった位置に間口１．９ｍ、方柱を１対立て、上部は笠石状につくる。両側から袖塀を円弧状に前方へ延ばし、通り沿いの塀と繋いだ特徴的な表構えを形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006349"},{"id":"00001972","register_sub_id":"101","register_pk":"102962","name":"西尾家住宅蔵","kana":"にしおけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県安芸郡奈半利町乙1578","lat":33.42567807,"lng":134.02125283,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"39 － 0022","desc":"敷地の東南隅に建つ桁行３間，梁行２間規模の東西棟，切妻造，桟瓦葺２階建土蔵で，北面中央西寄りに入口を設ける。当地方特有の土佐漆喰塗壁に水切瓦を三段付け，東・南・西の三面に回す。敷地南辺のレンガ塀とともに特色ある背面景観をつくりだしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001972"},{"id":"00001971","register_sub_id":"101","register_pk":"102961","name":"西尾家住宅台所","kana":"にしおけじゅうたくだいどころ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"高知県","address":"高知県安芸郡奈半利町乙1578","lat":33.42577228,"lng":134.02130497,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋建、瓦葺、建築面積35㎡","structure_material":"木造平屋建","registered":"2000.10.18(平成12.10.18)","register_no":"39 － 0021","desc":"主屋平屋部の南方に建つ桁行３間，梁行２間規模の南北棟，入母屋造，桟瓦葺建屋で，正面の西面と南面に下屋を回し，南に延びる角屋屋根に連ねる。内部には，４畳半規模の畳と板敷きの座を残し，土間・井戸とともに当地方のカマヤの形式を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001971"},{"id":"00001973","register_sub_id":"101","register_pk":"102963","name":"西尾家住宅納屋","kana":"にしおけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県安芸郡奈半利町乙1578","lat":33.425755,"lng":134.02122104,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋建、瓦葺、建築面積24㎡","structure_material":"木造平屋建","registered":"2000.10.18(平成12.10.18)","register_no":"39 － 0023","desc":"主屋２階屋の南方，台所に向きあう位置に建つ。桁行４間半，梁行１間半規模の南北棟，寄棟造，桟瓦葺，木造平屋建で，北・東・南３面に下屋を回す。南側一部に座敷を設けるなど「離れ」としての機能ももたせる。主屋背後の中庭形式を構成する主要素のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001973"},{"id":"00001975","register_sub_id":"101","register_pk":"102965","name":"西尾家住宅便所","kana":"にしおけじゅうたくべんじょ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"高知県","address":"高知県安芸郡奈半利町乙1578","lat":33.42581362,"lng":134.021233,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋建、瓦葺、建築面積3.6㎡","structure_material":"木造平屋建","registered":"2000.10.18(平成12.10.18)","register_no":"39 － 0025","desc":"主屋２階屋の南方，納屋の北側に接して建ち，中庭を挟んで台所に向きあう。桁行２間半，梁行１間規模の南北棟，寄棟造，桟瓦葺建屋で，東面に４つの戸を付ける。小規模ながらしっかりした造りの便所で，屋敷構えの欠くことのできない要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001975"},{"id":"00001974","register_sub_id":"101","register_pk":"102964","name":"西尾家住宅レンガ塀","kana":"にしおけじゅうたくれんがべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県安芸郡奈半利町乙1578","lat":33.42568446,"lng":134.02117414,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"煉瓦造、延長10m","structure_material":"煉瓦造","registered":"2000.10.18(平成12.10.18)","register_no":"39 － 0024","desc":"敷地の西辺と南辺に建つ煉瓦造の塀で，納屋南西端から発し，敷地南西端で折れ曲がり，蔵南西端に取付く。南辺西寄りに出入口１所を開ける。煉瓦１枚厚，イギリス積で，基礎石の上に煉瓦２９段に積み小屋根を載せる。蔵の土佐漆喰の白と鮮やかな対照をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001974"},{"id":"00004064","register_sub_id":"101","register_pk":"105054","name":"西田家住宅蔵","kana":"にしだけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県吾川郡仁淀川町土居甲643","lat":33.60574757,"lng":133.1642865,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積24㎡","structure_material":"土蔵造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"39 － 0132","desc":"仁淀川支流池川川の川石で築いた基壇上に南北棟で建つ。桁行２間半梁間２間，置屋根式の切妻造，桟瓦葺，平入の２階建土蔵で，腰を簓子下見板張，上部を土佐漆喰塗とし，２段の水切瓦を回す。窓の上下にも水切瓦を付けるなど丁寧なつくりで際立っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004064"},{"id":"00003005","register_sub_id":"101","register_pk":"103995","name":"野口家住宅蔵","kana":"のぐちけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"高知県","address":"高知県香南市野市町深渕100","lat":33.57075655,"lng":133.68748005,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積31㎡","structure_material":"土蔵造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"39 － 0055","desc":"物部川の川石を積んだ基礎上に建つ東西棟，切妻造，桟瓦葺，置屋根形式の２階建土蔵。南面に１間分の下屋が付き，西側を番小屋に充てる。外部は，北面が押縁下見，東西妻面は腰を芋目地の海鼠壁とし，土佐の土蔵の特徴である水切り瓦を４段付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003005"},{"id":"00001981","register_sub_id":"101","register_pk":"102971","name":"野村家住宅主屋","kana":"のむらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県安芸郡奈半利町乙2578","lat":33.4265568,"lng":134.0234096,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積101㎡","structure_material":"木造平屋建","registered":"2000.10.18(平成12.10.18)","register_no":"39 － 0031","desc":"藩の年貢米を集める「倉床」と呼ばれる家柄の住宅。道路側近くに建つ桁行４間半，梁行４間規模の東西棟，切妻造で，南北両面に下屋を付ける。内部は田の字型間取，外部妻面は腰を板張，上部を土佐漆喰の三段水切瓦付きとするなど土佐民家の特色を良く伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001981"},{"id":"00001982","register_sub_id":"101","register_pk":"102972","name":"野村家住宅東石塀","kana":"のむらけじゅうたくひがしいしべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸郡奈半利町乙2578","lat":33.42654754,"lng":134.02346647,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"石造、延長23m","structure_material":"石造","registered":"2000.10.18(平成12.10.18)","register_no":"39 － 0032","desc":"敷地の東辺に位置し，主屋東妻面に沿って門柱から北へ向かう「いしぐろ」練塀。塀厚約４０ｃｍ，塀高１．６ｍ，延長約２３ｍで，亀甲積み基礎の上に割石面を道路側に見せて積み，頂部に瓦葺の小屋根を載せる。門から主屋玄関に向けて曲面状の袖塀が附属する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001982"},{"id":"00001983","register_sub_id":"101","register_pk":"102973","name":"野村家住宅南石塀","kana":"のむらけじゅうたくみなみいしべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸郡奈半利町乙2578","lat":33.42646701,"lng":134.02332401,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"石造、延長25m","structure_material":"石造","registered":"2000.10.18(平成12.10.18)","register_no":"39 － 0033","desc":"敷地の南辺，隣地との境堺に築造された延長２５ｍの「いしぐろ」練塀。東石塀と同様に，塀厚約４０ｃｍ，塀高１．６ｍと他の箇所の「いしぐろ」と比べてやや小振りで，端部の納まりも割石積みとするなど素朴な趣を醸し出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001983"},{"id":"00004847","register_sub_id":"101","register_pk":"105837","name":"野村隆男家住宅井戸","kana":"のむらたかおけじゅうたくいど","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"高知県","address":"高知県安芸市土居994","lat":33.51867642,"lng":133.9114556,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"石造、面積0.71㎡","structure_material":"石造","registered":"2005.07.12(平成17.07.12)","register_no":"39 － 0193","desc":"主屋かま屋の北西方，薪置き場入口の前に穿たれる。上部直径９５ｃｍ，深さ約１０ｍで，内部は川原石を積み上げて築造する。現在はポンプ使用のため上部を塞いでいるが，内部構造に痛みはなく，当初の姿をよく留めている。往時の水事情を今に伝え貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004847"},{"id":"00004842","register_sub_id":"101","register_pk":"105832","name":"野村隆男家住宅主屋","kana":"のむらたかおけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"高知県","address":"高知県安芸市土居994","lat":33.51851369,"lng":133.91150708,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積98㎡、庭門二所付","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"39 － 0188","desc":"安芸土居城跡西南方の旧武家屋敷地に位置する。桁行５間梁行４間半，東西棟，切妻造，桟瓦葺の木造平屋建で，西妻面中央に式台玄関を設け，南側に４畳半・４畳・床付６畳，北側に４畳半・６畳を並べ，西北にかま屋を突き出す。武家住宅のつくりを伝え貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004842"},{"id":"00004845","register_sub_id":"101","register_pk":"105835","name":"野村隆男家住宅納屋","kana":"のむらたかおけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"江戸","pref":"高知県","address":"高知県安芸市土居994","lat":33.51863501,"lng":133.91141666,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積27㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"39 － 0191","desc":"主屋の北西方に位置し，屋敷地西辺沿いに南北棟で建つ。桁行２間梁間２間，切妻造，桟瓦葺，木造平屋建の物置の北に，桁行２間梁間１間，切妻造，桟瓦葺，木造平屋建の米蔵が落棟で続き，東面に土間庇を差し掛けて戸口を設ける。裏庭部周囲を構成する要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004845"},{"id":"00004848","register_sub_id":"101","register_pk":"105838","name":"野村隆男家住宅塀","kana":"のむらたかおけじゅうたくへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"高知県","address":"高知県安芸市土居994","lat":33.5184704,"lng":133.91143177,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土塀、瓦葺、延長7.0m","structure_material":"土塀","registered":"2005.07.12(平成17.07.12)","register_no":"39 － 0194","desc":"門南方と，主屋西南端に取り付く南塀重門とを東西に結ぶ屋敷地内の間仕切塀。高さ１．７ｍ，厚さ０．３ｍ，長さ７ｍ規模で，割れ瓦を赤土で積み上げ，頂部に瓦屋根を載せる。瓦の産地である安芸地方によく見ることの出来る瓦練塀の好事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004848"},{"id":"00004844","register_sub_id":"101","register_pk":"105834","name":"野村隆男家住宅便所・風呂棟","kana":"のむらたかおけじゅうたくべんじょ・ふろとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"高知県","address":"高知県安芸市土居994","lat":33.51856917,"lng":133.91142366,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積7.4㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"39 － 0190","desc":"門の北方に位置し，屋敷地西辺沿いに南北棟で建つ。桁行２間梁間１間，切妻造，桟瓦葺（東面に左瓦を使用）の木造平屋建で，内部は南側を浴室，北側を便所とする。外部は東面に出入口を設け，西面は腰押縁下見板張，上部漆喰塗として正面の構えを整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004844"},{"id":"00004846","register_sub_id":"101","register_pk":"105836","name":"野村隆男家住宅薪置き場","kana":"のむらたかおけじゅうたくまきおきば","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"高知県","address":"高知県安芸市土居994","lat":33.51871046,"lng":133.91140635,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積19㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"39 － 0192","desc":"屋敷地の北西隅に位置し，南北棟で建つ。桁行２間梁間１間，切妻造，桟瓦葺の木造平屋建で，納屋の米蔵との間に，桁行２間，切妻造，桟瓦葺で東面を吹放ちとした廊状部を落棟で挟み込む。外部は西北面を腰下見板張，上部漆喰塗として屋敷地角の景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004846"},{"id":"00004843","register_sub_id":"101","register_pk":"105833","name":"野村隆男家住宅門","kana":"のむらたかおけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"高知県","address":"高知県安芸市土居994","lat":33.5185051,"lng":133.91140959,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口3.6m","structure_material":"木造","registered":"2005.07.12(平成17.07.12)","register_no":"39 － 0189","desc":"屋敷地西辺中央の南寄りに位置する。桁行２間，南北棟，切妻造，東面に左瓦を用いた桟瓦葺の薬医門で，柱は７寸角を用い，前面と背面に控柱を添える。門口の両脇に腰下見板張の壁を付け，引き分け戸を建て込む。簡素な門であるが，屋敷正面構えの中心的存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004843"},{"id":"00004836","register_sub_id":"101","register_pk":"105826","name":"野村典男家住宅主屋","kana":"のむらのりおけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸市土居989","lat":33.51894955,"lng":133.91117482,"geo_status":"db","era":"明治40頃","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積87㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"39 － 0182","desc":"安芸土居城跡西方の旧武家屋敷地に位置する。桁行５間梁行３間半規模，東西棟，寄棟造，桟瓦葺の木造平屋建の東南に東西棟，入母屋造の離れと，西北に南北棟，切妻造のかま屋が附属する。南面を開放とし，東・北面に左瓦を用いた風土に合わせたつくりに特色。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004836"},{"id":"00004065","register_sub_id":"101","register_pk":"105055","name":"橋本家住宅石垣及び塀","kana":"はしもとけじゅうたくいしがきおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"高知県","address":"高知県吾川郡仁淀川町土居甲726-1","lat":33.60658025,"lng":133.16603104,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"鉄筋コンクリート造、延長22m","structure_material":"鉄筋コンクリート造","registered":"2004.03.02(平成16.03.02)","register_no":"39 － 0133","desc":"道路から一段上がった屋敷地までの石垣とその上に築かれた門柱及び塀。石垣はやや大振りの川石で築き，塀は高さ０．９ｍ，門柱は０．２３ｍ角，高１．８３ｍのＲＣ造。塀に貝文と七宝文の浮彫模様を格間毎交互に描いているのが特徴で，地域で目立つ存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004065"},{"id":"00000106","register_sub_id":"101","register_pk":"101096","name":"畠中家住宅（野良時計）蔵","kana":"はたけなかけじゅうたく（のらどけい）くら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸市土居638-4","lat":33.51575943,"lng":133.91154279,"geo_status":"db","era":"明治20","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造2階建、瓦葺、建築面積21㎡","structure_material":"木造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"39 － 0002","desc":"時計台のある主屋に近接して建つ大壁造の土蔵は，腰下を板張りとし，妻壁に開いた小窓と水切りの小庇で外観を飾る。「時計台」の載る主屋とともに，静かな田園地帯によくなじんだ風景として知られ親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000106"},{"id":"00000105","register_sub_id":"101","register_pk":"101095","name":"畠中家住宅（野良時計）主屋","kana":"はたけなかけじゅうたく（のらどけい）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸市土居638-4","lat":33.51574991,"lng":133.9116253,"geo_status":"db","era":"明治20","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造2階建、瓦葺、建築面積126㎡","structure_material":"木造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"39 － 0001","desc":"複雑な平面になる主屋北側の突出部の屋根に擬洋風の時計台が載る独特の構成を持つ。時計は当時の亭主の手造りと思われ，我が国の近代化が地方に浸透した過程を示す。「野良時計」の愛称でよく知られた住宅で，広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000105"},{"id":"00008208","register_sub_id":"101","register_pk":"132733","name":"畠中家住宅米蔵及び衣装蔵","kana":"はたけなかけじゅうたくこめぐらおよびいしょうぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸市土居字東高園633","lat":33.51532899,"lng":133.91133774,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造平屋一部2階建、瓦葺、建築面積60㎡","structure_material":"土蔵造平屋一部2階建","registered":"2010.04.28(平成22.04.28)","register_no":"39 － 0261","desc":"主屋の西方に南北棟で建つ。桁行１１ｍ梁間３．８ｍの土蔵造平屋一部２階建。切妻造桟瓦葺で、東面に深い庇を付け、庇南端に便所を造る。上部に窓を穿ち、鉄扉を吊り、内部は三室に分け南端を衣装蔵とする。土佐漆喰仕上げ、左桟瓦を使うなど地域性を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008208"},{"id":"00008207","register_sub_id":"101","register_pk":"132732","name":"畠中家住宅主屋","kana":"はたけなかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸市土居字東高園633","lat":33.5153224,"lng":133.91149307,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積182㎡、北蔵及び釜屋付","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"39 － 0260","desc":"敷地の中央に南面して建つ。切妻造桟瓦葺で、周囲に庇をまわし、背面に２階建の釜屋を付設。西に玄関や茶の間を置き、東半部は田の字型に表座敷や次の間などを配し、南に幅広の縁を通す。表座敷は天井が高く、良質なトコやトコ脇を構える、明朗な室空間である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008207"},{"id":"00008214","register_sub_id":"101","register_pk":"132739","name":"畠中家住宅外塀","kana":"はたけなかけじゅうたくそとべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸市土居字東高園633","lat":33.51519061,"lng":133.91151754,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"瓦積及び練石積、瓦葺、延長44m","structure_material":"瓦積及び練石積","registered":"2010.04.28(平成22.04.28)","register_no":"39 － 0267","desc":"敷地東辺及び南・北辺の東寄りを画す塀で、総延長４４ｍを測る。亀甲積基礎上に瓦を積む練塀で、隅は柱風にモルタルを塗る。左桟瓦や右桟瓦を使い分ける。東面中ほどにおいては川石を積むイシグロ風の仕上げとするなど、変化のある屋敷構えを造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008214"},{"id":"00008209","register_sub_id":"101","register_pk":"132734","name":"畠中家住宅道具蔵","kana":"はたけなかけじゅうたくどうぐぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸市土居字東高園633","lat":33.51543254,"lng":133.91135563,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積34㎡","structure_material":"土蔵造2階建","registered":"2010.04.28(平成22.04.28)","register_no":"39 － 0262","desc":"主屋釜屋の西に位置する。桁行６．６ｍ梁間４．５ｍの２階建土蔵。東西棟の切妻造桟瓦葺の置屋根とし、南面には庇を設け、蔵前とする。外壁は腰高に竪板を張り、上部は土佐漆喰で仕上げ、水切り瓦を数段まわす。釜屋と一連で屋敷地背後に重厚な景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008209"},{"id":"00008213","register_sub_id":"101","register_pk":"132738","name":"畠中家住宅中門","kana":"はたけなかけじゅうたくなかもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸市土居字東高園633","lat":33.51526515,"lng":133.91142888,"geo_status":"db","era":"明治19年","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"木造、瓦葺、間口4.0m、塀付","structure_material":"木造","registered":"2010.04.28(平成22.04.28)","register_no":"39 － 0266","desc":"主屋西南隅から番小屋にかけて、南北に中仕切り塀を設置し、その中ほどに中門を構える。中門は間口４．０ｍに本柱を建て、楣で固め、五通りの腕木が軒桁を持ち出すなど、本門を簡易にした構造になる。中仕切り塀は板塀で瓦葺。通路と作業場を明確に区分する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008213"},{"id":"00008215","register_sub_id":"101","register_pk":"132740","name":"畠中家住宅庭門及び築地塀","kana":"はたけなかけじゅうたくにわもんおよびついじべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸市土居字東高園633","lat":33.51527156,"lng":133.91146294,"geo_status":"db","era":"明治19年","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"木造、瓦葺、間口2.0m、延長10m","structure_material":"木造","registered":"2010.04.28(平成22.04.28)","register_no":"39 － 0268","desc":"本門から主屋玄関への通路と庭とを区切る。庭門は間口２．０ｍの腕木門。切妻造で左桟瓦と右桟瓦を使い分ける。庭側に控えを設け、引戸をたてる。築地塀は折曲り総延長１０ｍ。亀甲積基壇上に土台を設け、腰下見板張、上部漆喰仕上げ。良好な庭園景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008215"},{"id":"00008210","register_sub_id":"101","register_pk":"132735","name":"畠中家住宅番小屋","kana":"はたけなかけじゅうたくばんごや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"高知県","address":"高知県安芸市土居字東高園633","lat":33.51522355,"lng":133.91138669,"geo_status":"db","era":"明治19年","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積19㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"39 － 0263","desc":"敷地の西南隅に東西棟で建つ。桁行６．８ｍ梁間２．８ｍの木造平屋建、切妻造桟瓦葺で、棟は青海波状に平瓦で飾る。亀甲積基礎上に建ち、腰高に下見板を張り、上部を土佐漆喰仕上げとし、南面には細い格子の窓を開ける。本門とともに屋敷表構えを構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008210"},{"id":"00008212","register_sub_id":"101","register_pk":"132737","name":"畠中家住宅本門","kana":"はたけなかけじゅうたくほんもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸市土居字東高園633","lat":33.51520555,"lng":133.91145088,"geo_status":"db","era":"明治19年","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"木造、瓦葺、間口4.0m、袖塀及び石橋付","structure_material":"木造","registered":"2010.04.28(平成22.04.28)","register_no":"39 － 0265","desc":"敷地の南辺中央に位置する。間口４．０ｍに本柱を建て、冠木で固め、五通りに腕木を出し、軒桁を支持。一軒疎垂木、桟瓦葺とし、棟は青海波。本柱前後に控えを設け、貫で繋ぎ、脇に板塀を付設。間口は西端に戸袋を設け、扉を引き込むなど特異な造りとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008212"},{"id":"00008211","register_sub_id":"101","register_pk":"132736","name":"畠中家住宅薪小屋","kana":"はたけなかけじゅうたくまきごや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"高知県","address":"高知県安芸市土居字東高園633","lat":33.51527439,"lng":133.91137822,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積16㎡、風呂場付","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"39 － 0264","desc":"衣装蔵の庇南端から延びる桁行９．５ｍ梁間１．９ｍの木造平屋建。切妻造で、左桟瓦を葺く。北寄りに風呂などを設け、その南を薪の保管場所、南端を味噌倉とする。風呂の腰まわりには煉瓦を積む。高く下見板を張り、上部を土佐漆喰仕上げとする軽快な建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008211"},{"id":"00003735","register_sub_id":"101","register_pk":"104725","name":"濱川家住宅離れ","kana":"はまかわけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県安芸郡田野町字西町1880-1","lat":33.42765931,"lng":134.00999364,"geo_status":"db","era":"大正8／昭和7移築","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積85㎡","structure_material":"木造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"39 － 0092","desc":"蔵の北方に南北棟で建つ。桁行４間半梁間２間半規模，寄棟造，桟瓦葺で，３面に下屋を廻し，東面南寄りに入母屋造の玄関を突出させる。１０畳と８畳の座敷を南北に並べ，南面に縁側を付ける。もとの別荘を昭和７年主屋として現在地に移築と伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003735"},{"id":"00004467","register_sub_id":"101","register_pk":"105457","name":"濱田典彌家住宅石垣塀","kana":"はまだのりひろけじゅうたくいしがきべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"高知県","address":"高知県安芸郡奈半利町乙1028-1","lat":33.42242242,"lng":134.02269992,"geo_status":"db","era":"昭和9頃","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"コンクリート造、延長24m","structure_material":"コンクリート造","registered":"2004.11.08(平成16.11.08)","register_no":"39 － 0181","desc":"屋敷地の東南隅を区切る塀。浜石を用いたコンクリート練積塀で，厚さ０．３ｍ，高さ１．９ｍ，折れ曲がり延長２４ｍに造る。出隅部はセメント煉瓦を隅石状に積み，頂部にも同様のセメント煉瓦の笠石を置く。当地で「豆板塀」と呼ばれる石垣塀の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004467"},{"id":"00004464","register_sub_id":"101","register_pk":"105454","name":"濱田典彌家住宅かま屋","kana":"はまだのりひろけじゅうたくかまや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"高知県","address":"高知県安芸郡奈半利町乙1028-1","lat":33.42239848,"lng":134.02255952,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積67㎡、井戸付","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"39 － 0178","desc":"主屋の東面に東西棟で取り付き，南北両面に下屋を差し掛ける。切妻造，桟瓦葺の木造平屋建で，桁行３間半梁行４間の平面規模。南側に縁と６畳，その北に４畳大の女中部屋と６畳大の土間，東側南方に便所・浴室を配し，北方の井戸場は東面を吹き放ちとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004464"},{"id":"00004465","register_sub_id":"101","register_pk":"105455","name":"濱田典彌家住宅米あずかり場","kana":"はまだのりひろけじゅうたくこめあずかりば","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"高知県","address":"高知県安芸郡奈半利町乙1028-1","lat":33.42242764,"lng":134.02248892,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積37㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"39 － 0179","desc":"かま屋の北に接して南北棟で建ち，西面縁廊下で主屋北東隅に連絡する。桁行３間梁行２間半，入母屋造，桟瓦葺の木造平屋建で，四面に下屋を廻した形態をとる。内部は５畳大の床上部と３畳大の土間から構成される。地主住宅の屋敷構えの一端を物語る施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004465"},{"id":"00004463","register_sub_id":"101","register_pk":"105453","name":"濱田典彌家住宅主屋","kana":"はまだのりひろけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"高知県","address":"高知県安芸郡奈半利町乙1028-1","lat":33.42235205,"lng":134.02253913,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積116㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"39 － 0177","desc":"東西棟，桟瓦葺，入母屋屋根の４面に下屋を廻し，平面規模を桁行５間半梁行５間とし，北面に入母屋造の玄関と切妻造の便所を突出させる。内部は４室で，西南の８畳は床と書院を備える。屋根の起りと反り，狐格子と懸魚による妻飾りなど端正な造形意匠に特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004463"},{"id":"00004466","register_sub_id":"101","register_pk":"105456","name":"濱田典彌家住宅土蔵","kana":"はまだのりひろけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸郡奈半利町乙1028-1","lat":33.42227485,"lng":134.02263525,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積62㎡","structure_material":"土蔵造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"39 － 0180","desc":"主屋の南西方に位置する。桁行５間梁間３間規模，切妻造，桟瓦葺の２階建土蔵で，北面に下屋庇を差し掛けて観音扉付き戸口２箇所を開ける。石積基礎の上に建ち，腰を海鼠壁，上部を土佐漆喰塗とし，妻面には６段の水切瓦を付けるなど丁寧なつくりである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004466"},{"id":"00003166","register_sub_id":"101","register_pk":"104156","name":"東山家住宅石塀","kana":"ひがしやまけじゅうたくいしべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸郡奈半利町乙1281-2","lat":33.42335669,"lng":134.02140702,"geo_status":"db","era":"明治38頃","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"石造、瓦葺、延長3.2m","structure_material":"石造","registered":"2003.01.31(平成15.01.31)","register_no":"39 － 0070","desc":"敷地の東辺を区切る境界塀の一部。高さ１．８ｍ，厚み０．５ｍ規模で，浜石の長手が庭側に見えるように練積みとし，上部に桟瓦を載せる。残存部は長さ３．２ｍと極一部であるが，北端は隅石を４段積んで納める本格的な玉石練積塀になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003166"},{"id":"00003164","register_sub_id":"101","register_pk":"104154","name":"東山家住宅便所・風呂棟","kana":"ひがしやまけじゅうたくべんじょ・ふろとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"高知県","address":"高知県安芸郡奈半利町乙1281-2","lat":33.42340778,"lng":134.02122571,"geo_status":"db","era":"明治38頃","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積14㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"39 － 0068","desc":"主屋の南方に建つ。桁行２間半梁間１間半規模，南北棟，寄棟造，左瓦と右瓦を使い分けた桟瓦葺の木造平屋建で，南東端に五右衛門風呂を据える。浴室床，便所の他，外部の腰まで３０ｃｍ角の装飾タイルを張り巡らしているのが特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003164"},{"id":"00003769","register_sub_id":"101","register_pk":"104759","name":"百年舎内塀","kana":"ひゃくねんやうちべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"高知県","address":"高知県香美市土佐山田町東本町2-80","lat":33.60737973,"lng":133.68676786,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"鉄筋コンクリート造、延長22m","structure_material":"鉄筋コンクリート造","registered":"2003.12.01(平成15.12.01)","register_no":"39 － 0126","desc":"高さ１．６ｍの鉄筋コンクリート造の塀で，主屋北面の前庭をＬ字型に取り囲む。頂部には松皮菱状の笠木を置き，その下に鋸歯紋風の縁取を廻し，壁面中間にはゆったりとした山形折線を帯状に施している。いずれも特異な意匠だが，よく調和がとれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003769"},{"id":"00003767","register_sub_id":"101","register_pk":"104757","name":"百年舎蔵","kana":"ひゃくねんやくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県香美市土佐山田町東本町2-80","lat":33.60699167,"lng":133.68693799,"geo_status":"db","era":"大正中期","year":1919,"year_source":"estimated","year_min":1916,"year_max":1922,"year_label":"大正中期","structure":"土蔵造2階建、瓦葺、建築面積39㎡","structure_material":"土蔵造2階建","registered":"2003.12.01(平成15.12.01)","register_no":"39 － 0124","desc":"屋敷東南隅にある２階建の土蔵。南北棟の切妻造，平入で，西面に戸口を設け，下屋庇を架ける。屋根は置屋根式の桟瓦葺とし，深い軒をつくる。外壁は白漆喰や鼠漆喰を併用し，隅上部は算木風石張とし，水切瓦をつけるなど，外観の意匠にも創意がみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003767"},{"id":"00003766","register_sub_id":"101","register_pk":"104756","name":"百年舎主屋","kana":"ひゃくねんやしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県香美市土佐山田町東本町2-80","lat":33.6071981,"lng":133.68679215,"geo_status":"db","era":"明治23／大正6頃移築","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積201㎡","structure_material":"木造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"39 － 0123","desc":"桁行７間半梁間５間半規模，平屋建で，南北に長い屋敷のほぼ中央に建つ。桟瓦葺の屋根は東西棟の寄棟造だが，周囲は錣葺風に一段下げて段差をつけ，東南隅の突出部は切妻造で処理する。規模が大きく，全体として雄大な構えで，地域の中で際だった存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003766"},{"id":"00003770","register_sub_id":"101","register_pk":"104760","name":"百年舎外塀","kana":"ひゃくねんやそとべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"高知県","address":"高知県香美市土佐山田町東本町2-80","lat":33.60731541,"lng":133.68685792,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"鉄筋コンクリート造、延長18m","structure_material":"鉄筋コンクリート造","registered":"2003.12.01(平成15.12.01)","register_no":"39 － 0127","desc":"高さ１．６ｍの鉄筋コンクリート造の塀で，敷地西辺の北半を区画している。壁面のほぼ中間部分に曲線を帯びた菱形窓を点在させて上下に区分し，上部は２段の長方形窓を市松模様に開き，表面はドイツ壁風に仕上げ，頂部を笠石風とする。特異な意匠の塀である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003770"},{"id":"00003768","register_sub_id":"101","register_pk":"104758","name":"百年舎門","kana":"ひゃくねんやもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"高知県","address":"高知県香美市土佐山田町東本町2-80","lat":33.60728114,"lng":133.68680295,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造、瓦葺、間口1.5m","structure_material":"木造","registered":"2003.12.01(平成15.12.01)","register_no":"39 － 0125","desc":"北面して建つ主屋の北東端にあり，玄関と庭を区画している。間口１．５ｍの小規模な棟門で，扉は片引戸とする。軒は疎垂木，屋根は切妻造，桟瓦葺とする。背面の桁下には薬医門風に控え柱を立てる。簡素なつくりだが，屋敷のアプローチ空間を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003768"},{"id":"00003008","register_sub_id":"101","register_pk":"103998","name":"福田家住宅応接棟","kana":"ふくだけじゅうたくおうせつとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"高知県","address":"高知県香南市野市町東佐古105","lat":33.58957509,"lng":133.70558324,"geo_status":"db","era":"大正13頃","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積39㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"39 － 0058","desc":"客殿の南に接続して建つ。醸造場の事務所を兼ねた鉄筋コンクリート造洋館で，西を正面とし，桁行約７ｍ，梁間約５ｍ規模の陸屋根造とする。高知県下における鉄筋コンクリート造建築の初期の事例で，ドイツ壁風の外壁仕上げと屋上手摺装飾柱の意匠に特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003008"},{"id":"00003007","register_sub_id":"101","register_pk":"103997","name":"福田家住宅客殿及び離れ","kana":"ふくだけじゅうたくきゃくでんおよびはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県香南市野市町東佐古105","lat":33.589626,"lng":133.705658,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"土蔵造及び木造2階建、瓦葺、建築面積93㎡","structure_material":"土蔵造及び木造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"39 － 0057","desc":"住宅敷地の北西隅に建つ。桁行４間，梁間３間規模，南北棟，四周に庇を廻した入母屋造，２階建土蔵造の客殿の東方に，東西棟，真壁造の離れを角屋状に出す。客殿は１階を食堂等，２階を６畳２室とし，外観を水切り瓦により４層建に見せている点に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003007"},{"id":"00003009","register_sub_id":"101","register_pk":"103999","name":"福田家住宅蔵及び番小屋","kana":"ふくだけじゅうたくくらおよびばんごや","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"大正","pref":"高知県","address":"高知県香南市野市町東佐古105","lat":33.58950625,"lng":133.705582,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積28㎡","structure_material":"土蔵造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"39 － 0059","desc":"応接棟の南に南北棟で建つ。桁行２間半，梁間２間規模，置屋根形式の切妻造，桟瓦葺，２階建土蔵で，東面に下屋を差掛けて蔵前と３畳規模の番小屋に充てる。西面は腰簓子下見，上部土佐漆喰塗に２段の水切り瓦を付け，南北妻には水切りの上に鏝絵で波を描く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003009"},{"id":"00003006","register_sub_id":"101","register_pk":"103996","name":"福田家住宅主屋","kana":"ふくだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県香南市野市町東佐古105","lat":33.58960176,"lng":133.70580863,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積150㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"39 － 0056","desc":"住宅敷地の中央に東西棟で建つ。桁行７間半，梁行５間半規模，入母屋造で，東南西の３面に下屋を廻す。東南隅の１２畳半座敷を中心とした３列８室構成をとり，南面西寄りに入母屋造玄関を突き出す。高知における近代和風邸宅の好例で，漆喰鏝絵の妻飾に特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003006"},{"id":"00003013","register_sub_id":"101","register_pk":"104003","name":"福田家住宅外塀","kana":"ふくだけじゅうたくそとべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県香南市野市町東佐古105","lat":33.58965269,"lng":133.70592712,"geo_status":"db","era":"大正13頃","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート造、瓦葺、延長59m","structure_material":"鉄筋コンクリート造","registered":"2002.08.21(平成14.08.21)","register_no":"39 － 0063","desc":"住宅敷地の南・東・北面を囲う。高さ２．２ｍの鉄筋コンクリート塀で，桟瓦葺の屋根を載せ，北面西寄りに潜門１所を開く。外装はモルタル塗とし，モンドリアン風の幾何学的文様の目地を切る。応接棟などとともにモダンデザインを当地域にもたらした好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003013"},{"id":"00003012","register_sub_id":"101","register_pk":"104002","name":"福田家住宅庭門及び庭間仕切塀","kana":"ふくだけじゅうたくにわもんおよびにわまじきりべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県香南市野市町東佐古105","lat":33.58948878,"lng":133.70579253,"geo_status":"db","era":"大正13頃","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造、瓦葺、間口1.4m、及び鉄筋コンクリート造塀延長10m","structure_material":"木造","registered":"2002.08.21(平成14.08.21)","register_no":"39 － 0062","desc":"主屋玄関前から南庭に通じる門は２間１戸の木造棟門で，桟瓦葺の切妻屋根に起りを付ける。塀は庭が望見できるよう低く造り，出隅部から１段高くして住宅敷地南辺外塀に繋げるとともに，笠木部下には飾りを付け，玄関へのアプローチ景観を巧みに演出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003012"},{"id":"00003010","register_sub_id":"101","register_pk":"104000","name":"福田家住宅風呂及び便所","kana":"ふくだけじゅうたくふろおよびべんじょ","category":"住宅","subcategory":"建築物","type_guess":"塀","type_guess_confidence":"low","period":"大正","pref":"高知県","address":"高知県香南市野市町東佐古105","lat":33.58952757,"lng":133.70566815,"geo_status":"db","era":"大正13頃","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積22㎡、間仕切塀付","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"39 － 0060","desc":"応接棟・蔵及び番小屋の東方に南北棟で建ち，主屋の西南端に連絡する。桁行４間，梁間１間半規模，寄棟造，桟瓦葺の平屋建で，西面北寄りを外便所とする。西南端から応接棟にかけて矩折れに間仕切塀を付属させ，門から主屋玄関にかけての屋敷景観の構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003010"},{"id":"00003011","register_sub_id":"101","register_pk":"104001","name":"福田家住宅門","kana":"ふくだけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県香南市野市町東佐古105","lat":33.58946448,"lng":133.70555967,"geo_status":"db","era":"大正13頃","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート造、瓦葺、間口3.7m","structure_material":"鉄筋コンクリート造","registered":"2002.08.21(平成14.08.21)","register_no":"39 － 0061","desc":"蔵及び番小屋の南に建つ。間口２間規模で，事業用と住宅用を兼ねる。門柱，冠木，女梁及び控柱を鉄筋コンクリートで造り，梁から上を木造として桟瓦葺の切妻屋根をつくる。応接棟とともに県下における初期の鉄筋コンクリート造の事例として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003011"},{"id":"00003744","register_sub_id":"101","register_pk":"104734","name":"普光江家住宅蔵","kana":"ふこうえけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸郡田野町2051","lat":33.42767956,"lng":134.01036275,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造平屋建、瓦葺、建築面積19㎡","structure_material":"土蔵造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"39 － 0101","desc":"主屋東棟の南方に東西棟で建つ。桁行２間半梁間１間半規模，切妻造，桟瓦葺の平屋建，平入土蔵で，内部は２室に分けられ，北面に半間幅の下屋を差し掛けて蔵前をとる。土佐漆喰塗壁に水切瓦を妻面と下屋の付け根に付けて当地特有の土蔵建築の外観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003744"},{"id":"00003745","register_sub_id":"101","register_pk":"104735","name":"普光江家住宅納屋","kana":"ふこうえけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸郡田野町2051","lat":33.42767931,"lng":134.01026344,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積27㎡","structure_material":"木造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"39 － 0102","desc":"主屋西棟の南方，蔵の西方に位置する東西棟，切妻造，桟瓦葺の木造平屋建で，桁行２間半梁間１間半のほぼ同規模の２棟から成る。東納屋は西納屋より棟をやや落として建ち，左瓦を使用する。ともに簡素なつくりながら，商家奥向きの構えに欠かせない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003745"},{"id":"00004080","register_sub_id":"101","register_pk":"105070","name":"松岡家住宅石垣・門及び塀","kana":"まつおかけじゅうたくいしがき・もんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県高岡郡日高村本郷1887","lat":33.53187235,"lng":133.35214101,"geo_status":"db","era":"大正初期／昭和初期増築","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"石造、延長22m","structure_material":"石造","registered":"2004.03.02(平成16.03.02)","register_no":"39 － 0148","desc":"敷地の正面と背面に築かれる。瘤出仕上の亀甲積石垣の上に，背面に控壁を付した長手積の煉瓦塀と，柱形付のＲＣ造塀をのせ，全体に軒蛇腹を付し桟瓦を葺く。重厚かつ精緻な石垣と，丁寧なつくりの近代的な塀が，屋敷構に風格を与えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004080"},{"id":"00004076","register_sub_id":"101","register_pk":"105066","name":"松岡家住宅米蔵","kana":"まつおかけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県高岡郡日高村本郷1887","lat":33.53195161,"lng":133.35227577,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"土蔵造2階建、瓦葺、建築面積30㎡","structure_material":"土蔵造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"39 － 0144","desc":"敷地の東南端の角に構える。桁行４間梁間３間，南北棟，切妻造，桟瓦葺の土蔵造２階建。基礎は亀甲積石垣で，腰を簓子下見板張，上部に漆喰を塗り込め，軒裏を鉢巻状とする本格的なつくり。軒を深く張り出し，外壁に２層から３層の水切瓦を廻らすのが特徴的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004076"},{"id":"00004069","register_sub_id":"101","register_pk":"105059","name":"松岡家住宅主屋","kana":"まつおかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"高知県","address":"高知県高岡郡日高村本郷1887","lat":33.53204278,"lng":133.35216475,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積181㎡","structure_material":"木造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"39 － 0137","desc":"国道３３号に近く，村中心地に対して西側のやや高台に位置する。桁行９間梁間５間半の木造２階建，入母屋造，桟瓦葺で，土佐漆喰仕上の真壁造とし，正面土間玄関の黒漆喰が重厚感を醸し出す。南面には径の大きい丸太桁を用い，陰影に富む深い軒をつくりだす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004069"},{"id":"00004070","register_sub_id":"101","register_pk":"105060","name":"松岡家住宅主屋門及び塀","kana":"まつおかけじゅうたくしゅおくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"高知県","address":"高知県高岡郡日高村本郷1887","lat":33.53195404,"lng":133.35217471,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造、瓦葺、間口1.8m、鉄筋コンクリート造、延長12m","structure_material":"木造","registered":"2004.03.02(平成16.03.02)","register_no":"39 － 0138","desc":"主屋玄関前に建つ切妻造，桟瓦葺，間口１間の薬医門と，その両脇のコンクリート造の塀。主屋門には欅材が用いられ，妻に本懸魚及び降り懸魚を付し，外装モルタル洗出仕上とした桟瓦葺の塀には，柱形や軒蛇腹をつくりだすなど，全体として丁寧なつくりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004070"},{"id":"00004079","register_sub_id":"101","register_pk":"105069","name":"松岡家住宅酒造場門及び塀","kana":"まつおかけじゅうたくしゅぞうじょうもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"高知県","address":"高知県高岡郡日高村本郷1887","lat":33.53195623,"lng":133.3520972,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"鉄筋コンクリート造、延長6m","structure_material":"鉄筋コンクリート造","registered":"2004.03.02(平成16.03.02)","register_no":"39 － 0147","desc":"敷地中央部に位置する。間口２ｍのＲＣ造門柱の両脇に，石積風の目地を切ったＲＣ造塀が付く。直線状の左袖塀は離れに接続し，曲線平面の右袖塀端部にも柱をたてる。醸造所の作業空間と住宅部の生活空間を仕切る敷地の一つの要となる工作物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004079"},{"id":"00004075","register_sub_id":"101","register_pk":"105065","name":"松岡家住宅離れ","kana":"まつおかけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県高岡郡日高村本郷1887","lat":33.53191107,"lng":133.35212869,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋建、瓦葺、建築面積8.9㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"39 － 0143","desc":"主屋の南側に位置し，敷地南面に構える煉瓦塀に接続して建つ。当初酒造研究室として使用。２間四方の木造平屋建，桟瓦葺，寄棟造で，一軒疎垂木とする。基礎の石垣は亀甲積で，戸袋と腰を簓子下見板張とし，上部を真壁造に見せる。小規模ながら丁寧なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004075"},{"id":"00004077","register_sub_id":"101","register_pk":"105067","name":"松岡家住宅便所","kana":"まつおかけじゅうたくべんじょ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"高知県","address":"高知県高岡郡日高村本郷1887","lat":33.53210674,"lng":133.35208326,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積7.2㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"39 － 0145","desc":"敷地北側，主屋の背面西側に位置する。木造平屋建，桟瓦葺，切妻造で，梁に真束をたてる。１間半四方の規模を有し，東面の腰を目地入りのモルタル塗で仕上げ，その上部にガラス引き違い窓を設ける。内部は改修されているが，特に西面は当初の姿をよく留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004077"},{"id":"00004078","register_sub_id":"101","register_pk":"105068","name":"松岡家住宅浴室","kana":"まつおかけじゅうたくよくしつ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"高知県","address":"高知県高岡郡日高村本郷1887","lat":33.53211223,"lng":133.35212636,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"鉄筋コンクリート造平屋造、建築面積10㎡","structure_material":"鉄筋コンクリート造平屋造","registered":"2004.03.02(平成16.03.02)","register_no":"39 － 0146","desc":"敷地北側，主屋の中央背面に位置する。平面規模４．６ｍ×２．２ｍのＲＣ造平屋建で，屋根は陸屋根，外装は目地入りのモルタル塗とする。軒蛇腹を付け，隅部などに柱形をつくり，入口上部に曲線状の庇を設けるなど，小規模ながら意匠を凝らしたつくりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004078"},{"id":"00003476","register_sub_id":"101","register_pk":"104466","name":"松尾酒造表門及び塀","kana":"まつおしゅぞうおもてもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県香美市土佐山田町西本町5-1","lat":33.6040537,"lng":133.68016879,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造、瓦葺、間口3.6m、土塀、瓦葺、延長10m","structure_material":"木造","registered":"2003.07.01(平成15.07.01)","register_no":"39 － 0079","desc":"主屋式台玄関の北方に建つ。表門は間口２間規模の薬医門で，屋根は切妻造，桟瓦葺とし緩やかな起りをつける。正面右手は脇門，左手は煉瓦造の袖塀とし，東方及び西方へ旧街道沿いに擬石仕上げの土塀を接続させる。主屋北面とともに街頭景観を構成する主要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003476"},{"id":"00003472","register_sub_id":"101","register_pk":"104462","name":"松尾酒造主屋","kana":"まつおしゅぞうしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県香美市土佐山田町西本町5-1","lat":33.603954,"lng":133.680237,"geo_status":"db","era":"大正元","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積90㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"39 － 0075","desc":"旧街道に北面する角地の北寄りに建つ。南北棟，入母屋造，桟瓦葺の木造平屋建で，北と南面に下屋庇を差出し，東面は道路に面し縦板張に仕上げる。造り酒屋の来客用住居部分で，２段庇状の北面には式台玄関を設け重厚な表構えをつくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003472"},{"id":"00003477","register_sub_id":"101","register_pk":"104467","name":"松尾酒造煉瓦塀","kana":"まつおしゅぞうれんがべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県香美市土佐山田町西本町5-1","lat":33.60389017,"lng":133.68031448,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"煉瓦造、延長10m","structure_material":"煉瓦造","registered":"2003.07.01(平成15.07.01)","register_no":"39 － 0080","desc":"主屋南面と北酒蔵北面の間に位置する坪庭の東辺を画する外塀。煉瓦１枚厚で，小口積とし，煉瓦３５段に積む。後に主屋寄りを改造して楕円アーチの出入口を設ける。北酒蔵の白漆喰塗壁と鮮やかな対照をなし，東側道路沿いに変化ある景観をつくりだしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003477"},{"id":"00006265","register_sub_id":"101","register_pk":"107249","name":"南家住宅蔵","kana":"みなみけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸郡安田町大字安田1080","lat":33.43986106,"lng":133.98221901,"geo_status":"db","era":"明治後期／昭和30頃曳家","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"39 － 0213","desc":"主屋の東側に，道路に面して建つ。桁行３間半，梁間２間で，土蔵造２階建，切妻造，桟瓦葺とする。置屋根の形式で，南面に戸口を設け，平側は腰を縦板張とし，２階に２つの窓を開く。東面以外には水切り瓦を設け，地域的に特色のある外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006265"},{"id":"00006263","register_sub_id":"101","register_pk":"107247","name":"南家住宅主屋","kana":"みなみけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸郡安田町大字安田1080","lat":33.4398634,"lng":133.98210956,"geo_status":"db","era":"明治後期／昭和30頃曳家","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積100㎡","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"39 － 0212","desc":"北側道路に面して建つ町家建築。桁行４間半，梁間６間の規模で，木造平屋建，切妻造，桟瓦葺とする。表土間をもち，奥に４畳半間の座敷を配し，南西隅の台所を土間とする。正面下屋上部の漆喰壁の一部に格子窓を開く。水切り瓦を付け，地方色のある外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006263"},{"id":"00006266","register_sub_id":"101","register_pk":"107250","name":"南家住宅便所及び風呂","kana":"みなみけじゅうたくべんじょおよびふろ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"高知県","address":"高知県安芸郡安田町大字安田1080","lat":33.43978506,"lng":133.98209601,"geo_status":"db","era":"明治後期／昭和30頃曳家","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積9.2㎡","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"39 － 0214","desc":"主屋の南側に建つ。桁行２間半，梁間１間半の規模で，木造平屋建，切妻造，桟瓦葺とする。東側を風呂，西側を便所とし，北西隅に出入口を付ける。外壁を縦羽目板張とし，屋根に若干の起りをつける。主屋とやや間隔を空けて建ち，地域的特色を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006266"},{"id":"00001977","register_sub_id":"101","register_pk":"102967","name":"森家住宅（旧野村茂久馬邸）蔵","kana":"もりけじゅうたく（きゅうのむらもくまてい）くら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸郡奈半利町乙2595","lat":33.42710521,"lng":134.02386111,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積50㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"39 － 0027","desc":"敷地の北側で，主屋２階屋の東方に主屋とは棟を直交させる形で建つ。棟違いの３棟が一体となった土蔵で，全体の規模は桁行方向で４間半，梁行２間，南面に下屋を付けて３戸前共通の蔵前とする。茂久馬の先代の時代に建設と伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001977"},{"id":"00001976","register_sub_id":"101","register_pk":"102966","name":"森家住宅（旧野村茂久馬邸）主屋","kana":"もりけじゅうたく（きゅうのむらもくまてい）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県安芸郡奈半利町乙2595","lat":33.42704805,"lng":134.02372866,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造2階建、瓦葺、建築面積218㎡","structure_material":"木造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"39 － 0026","desc":"土佐の交通王とされる野村茂久馬の奈半利邸として建設。道路に面した２階屋は，桁行１０間，梁行３間，南北棟，入母屋造，桟瓦葺で，外観は下見板張に縦長窓を開けた洋風仕様とし，東側に生活の場としての平屋を張り出す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001976"},{"id":"00001978","register_sub_id":"101","register_pk":"102968","name":"森家住宅（旧野村茂久馬邸）西石塀","kana":"もりけじゅうたく（きゅうのむらもくまてい）にしいしべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県安芸郡奈半利町乙2595","lat":33.4269631,"lng":134.02367365,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"石造、延長6m","structure_material":"石造","registered":"2000.10.18(平成12.10.18)","register_no":"39 － 0028","desc":"主屋２階屋の南西端から道路沿いに南方に延びる当地方特有の「いしぐろ」塀。切石積の基礎に浜石を練積みとし，頂部に瓦葺の小屋根を載せる。塀厚は５０ｃｍ，高さ２．５ｍ，延長６ｍで，両端部は切石の隅石で固める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001978"},{"id":"00001980","register_sub_id":"101","register_pk":"102970","name":"森家住宅（旧野村茂久馬邸）東石塀","kana":"もりけじゅうたく（きゅうのむらもくまてい）ひがしいしべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県安芸郡奈半利町乙2595","lat":33.42702437,"lng":134.02398952,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"石造、延長19m","structure_material":"石造","registered":"2000.10.18(平成12.10.18)","register_no":"39 － 0030","desc":"敷地の東辺に位置し，小路に沿って建つ。西石塀・南石塀と同様の端部を切石の隅石で納めた小屋根付き「いしぐろ」塀で，塀厚５０ｃｍ，塀高２．５ｍ，延長１９ｍ。ほぼ中央部に裏口１所を設け，煉瓦でアーチ状に開口をつくっている点に特色がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001980"},{"id":"00001979","register_sub_id":"101","register_pk":"102969","name":"森家住宅（旧野村茂久馬邸）南石塀","kana":"もりけじゅうたく（きゅうのむらもくまてい）みなみいしべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県安芸郡奈半利町乙2595","lat":33.42685402,"lng":134.02378239,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"石造、延長19m","structure_material":"石造","registered":"2000.10.18(平成12.10.18)","register_no":"39 － 0029","desc":"敷地の南辺に位置し，道路に沿って築造される。西石塀と同様に，奈半利特有のいわゆる「いしぐろ」練塀で，塀厚５０ｃｍ，塀高２．５ｍ，折れ曲がり延長１９ｍの規模を有する。屋敷構えを構成する要素であるとともに，奈半利特有の街路景観をもつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001979"},{"id":"00005048","register_sub_id":"101","register_pk":"106038","name":"森澤家住宅井戸屋","kana":"もりさわけじゅうたくいどや","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"高知県","address":"高知県安芸市土居559","lat":33.51494214,"lng":133.91190394,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造、瓦葺、建築面積10㎡","structure_material":"木造","registered":"2005.11.10(平成17.11.10)","register_no":"39 － 0202","desc":"主屋の北側に近接して東西棟で建ち，桁行３．６ｍ，梁間２．９ｍの規模で四方に柱を立て，切妻造，桟瓦葺の屋根を乗せ，両妻面に雨除けの板を張る。井戸は直径１．１ｍの円形で丸石を基礎から積み上げる。井戸周辺には河原石を円形に並べる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005048"},{"id":"00005051","register_sub_id":"101","register_pk":"106041","name":"森澤家住宅内塀","kana":"もりさわけじゅうたくうちべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸市土居559","lat":33.51496442,"lng":133.91193018,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"板塀及び土塀、瓦葺、総延長25m","structure_material":"板塀及び土塀","registered":"2005.11.10(平成17.11.10)","register_no":"39 － 0205","desc":"主屋北面のほぼ東半を囲う板塀と，離れ南庭を囲う土塀で，板塀は全長１２ｍ，高さ１．８ｍで，半間毎に柱を立て，柱間を板張りとする。土塀は長さ１３ｍ，高さ１．７ｍ，厚さ０．３ｍで，側面を漆喰塗りとする。両塀ともに上部に桟瓦葺屋根を乗せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005051"},{"id":"00005054","register_sub_id":"101","register_pk":"106044","name":"森澤家住宅外周石垣","kana":"もりさわけじゅうたくがいしゅういしがき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸市土居559","lat":33.5150223,"lng":133.91200582,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"石造、総延長59m","structure_material":"石造","registered":"2005.11.10(平成17.11.10)","register_no":"39 － 0208","desc":"敷地東辺と北辺の外周に造られた石垣で，東辺は建物の基礎石を兼ねる。敷地東辺南半長さ２６．３ｍおよび北辺長さ１４．６ｍを四角面の石積みとし，東辺北半長さ１８．５ｍを亀甲面の石積みとする。東辺南半が最も新しく，北面は若干のそりをもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005054"},{"id":"00005044","register_sub_id":"101","register_pk":"106034","name":"森澤家住宅北蔵","kana":"もりさわけじゅうたくきたぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸市土居559","lat":33.51507204,"lng":133.91180408,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積61㎡","structure_material":"土蔵造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"39 － 0198","desc":"敷地北西隅に南面して建ち，桁行６間，梁間３間半の規模。切妻造，桟瓦葺，２階建で，東半を米蔵，西半を道具蔵とする。正面に奥行１間の下屋を付け，その西端に１間四方の大工道具蔵を付属する｡上部漆喰壁に水切瓦４段を取り付け,地方色のある意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005044"},{"id":"00005050","register_sub_id":"101","register_pk":"106040","name":"森澤家住宅汲み池","kana":"もりさわけじゅうたくくみいけ","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"高知県","address":"高知県安芸市土居559","lat":33.51493407,"lng":133.91196976,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"石造、3基、石橋付","structure_material":"石造","registered":"2005.11.10(平成17.11.10)","register_no":"39 － 0204","desc":"主屋南東及び南西の敷地境の壁の内部に２基，離れ北側の敷地境に１基，共に石積みで築かれた水汲み場兼洗い場である。敷地東面に築かれた２基は，南部は切石で，北部は丸石で築かれ，水路に向けて給排水口をもつ。北側汲み池横の水路には石橋を架ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005050"},{"id":"00005042","register_sub_id":"101","register_pk":"106032","name":"森澤家住宅主屋","kana":"もりさわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸市土居559","lat":33.51487876,"lng":133.91183652,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積141㎡","structure_material":"木造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"39 － 0196","desc":"南北に長い敷地の中央に東西棟で建つ。桁行９間半，梁間４間半の規模とし，切妻造，桟瓦葺，平屋建で，西方に床上部九室，東方に土間，南面中央に式台玄関をとる。周囲半間に下屋を廻し，外壁を羽目板張りとする。明治の地主屋敷の大規模な主屋として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005042"},{"id":"00005053","register_sub_id":"101","register_pk":"106043","name":"森澤家住宅外塀","kana":"もりさわけじゅうたくそとべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸市土居559","lat":33.51488885,"lng":133.91197823,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造、瓦葺、延長21m","structure_material":"木造","registered":"2005.11.10(平成17.11.10)","register_no":"39 － 0207","desc":"敷地東辺の建物の間を繋ぐ外塀で，外周石垣の上に建ち，外壁を押縁付下見板とする。長屋門北端より２．９ｍ，漬物部屋北端より２０．６ｍの長さで，敷地側に柱等を立て，上部を桟瓦葺の切妻屋根とする。主屋東側は主屋の入母屋屋根の軒を張り出す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005053"},{"id":"00005052","register_sub_id":"101","register_pk":"106042","name":"森澤家住宅築地塀","kana":"もりさわけじゅうたくついじべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸市土居559","lat":33.51470394,"lng":133.91177468,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土塀、瓦葺、総延長26m","structure_material":"土塀","registered":"2005.11.10(平成17.11.10)","register_no":"39 － 0206","desc":"敷地南西隅の西辺と南辺に建ち，共に厚さ０．３ｍで，瓦屋根を乗せる。西辺は長さ１０．５ｍ，高さ１．８ｍ，玉石積みの上に漆喰塗りの土塀で，南辺は長さ１５ｍ，高さ１．８ｍ，石積みの上部に河原石の練り込んだ土塀を乗せ，特色ある外観を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005052"},{"id":"00005047","register_sub_id":"101","register_pk":"106037","name":"森澤家住宅漬物部屋","kana":"もりさわけじゅうたくつけものべや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"高知県","address":"高知県安芸市土居559","lat":33.51478586,"lng":133.91193711,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積17㎡","structure_material":"木造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"39 － 0201","desc":"主屋の南東の敷地境に接して南北棟で建ち，桁行３間半，梁間２間の規模で，切妻造，桟瓦葺，平屋建である。南北２室に分け，北側を漬物部屋として北面に出入口を付け，南側を物置として使用する。敷地境の外壁は押縁付下見板張りで，上部を土佐漆喰塗りとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005047"},{"id":"00005043","register_sub_id":"101","register_pk":"106033","name":"森澤家住宅長屋門","kana":"もりさわけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸市土居559","lat":33.51471613,"lng":133.91189767,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積30㎡","structure_material":"木造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"39 － 0197","desc":"敷地南東隅に南面して建ち，桁行５間半，梁間３間，切妻造，桟瓦葺，平屋建で，裏に半間の下屋を出し，東部に８畳間，西部に６畳間をとる。正面に開戸，その左右に武者窓を付け，外壁腰部分を押縁付下見板張，上部を土佐漆喰塗とし，格式ある屋敷構を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005043"},{"id":"00005046","register_sub_id":"101","register_pk":"106036","name":"森澤家住宅納屋","kana":"もりさわけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸市土居559","lat":33.51495797,"lng":133.91176528,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積39㎡","structure_material":"木造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"39 － 0200","desc":"主屋の北西の敷地境に東面して建ち，桁行５間半，梁間２間半の規模で，切妻造，桟瓦葺，２階建。１階を南北２室に分け２階を１室とし，１・２階共に物置として使用する。外壁は下部を板張りとし，上部を真壁土佐漆喰塗りとし，両妻に雨除けの板を付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005046"},{"id":"00005045","register_sub_id":"101","register_pk":"106035","name":"森澤家住宅離れ","kana":"もりさわけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸市土居559","lat":33.51505852,"lng":133.91195787,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積65㎡","structure_material":"木造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"39 － 0199","desc":"敷地北東隅に東西棟で建ち，桁行５間半，梁間３間で，切妻造，桟瓦葺，平屋建である。床棚付きの１０畳間に６畳間を続け，南側に縁を付け，南東端に便所を付ける。外壁は押縁付下見板張りとし，北面東寄りに幅２間の出格子窓を，東面南寄りに武者窓を付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005045"},{"id":"00005049","register_sub_id":"101","register_pk":"106039","name":"森澤家住宅便所及び風呂","kana":"もりさわけじゅうたくべんじょおよびふろ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"高知県","address":"高知県安芸市土居559","lat":33.514904,"lng":133.91174625,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積5.5㎡","structure_material":"木造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"39 － 0203","desc":"主屋西側の敷地境に南北棟で建つ。共に桁行２間，梁間１間の規模で隣接して建つ。南側の便所は切妻造で，北側の風呂は南側を入母屋造とし，共に桟瓦葺とする。便所は大便所３室を設け，風呂は浴槽をタイル貼りとし，南東隅に焚き口のある小室を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005049"},{"id":"00004060","register_sub_id":"101","register_pk":"105050","name":"山﨑家住宅蔵","kana":"やまさきけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"高知県","address":"高知県高知市鏡的渕71","lat":33.60247339,"lng":133.45860702,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、瓦葺、建築面積15㎡","structure_material":"土蔵造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"39 － 0128","desc":"的渕川沿い県道に南面する敷地の西南隅に建つ。桁行２間梁間１間半，置屋根式の切妻造，桟瓦葺，平入の２階建土蔵で，東面に下屋を差し掛けて蔵前をとる。腰を板張，上部を土佐漆喰塗とし，南妻面には土佐の土蔵に見られる水切瓦を３段に付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004060"},{"id":"00004061","register_sub_id":"101","register_pk":"105051","name":"山﨑家住宅敷地石垣及び水田石垣","kana":"やまさきけじゅうたくしきちいしがきおよびすいでんいしがき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"高知県","address":"高知県高知市鏡的渕71","lat":33.60260639,"lng":133.45859885,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"石造、延長35m","structure_material":"石造","registered":"2004.03.02(平成16.03.02)","register_no":"39 － 0129","desc":"県道と一段高い屋敷地の間を水田とし，東端に県道からの入口斜路を付ける。水田石垣は高さ１ｍ程で山石を用いて乱積とし，敷地石垣は高さ３．５ｍ程で弛みをつけて川石で積み，天端を亀甲積風にして整える。山村の江戸末以来の屋敷景観を伝えることで貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004061"},{"id":"00003758","register_sub_id":"101","register_pk":"104748","name":"隅田家住宅離れ","kana":null,"category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸郡田野町2363-1","lat":33.42719716,"lng":134.00358433,"geo_status":"db","era":"明治39","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"木造2階建一部平屋建、瓦葺、建築面積106㎡","structure_material":"木造2階建一部平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"39 － 0115","desc":"主屋の北方，裏通りに沿って東西棟で建つ。桁行４間半梁間３間半規模，切妻造，桟瓦葺の木造２階建で，南面に下屋を差し掛けて左瓦を葺き，東側に北納屋が附属する。内部は田の字型の４室構成とし，外観は土佐漆喰塗壁に水切瓦を廻した土蔵風の仕上げとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003758"},{"id":"00010899","register_sub_id":"101","register_pk":"201734","name":"伊佐家住宅主屋","kana":"いさけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"福岡県","address":"福岡県福岡市早良区高取一丁目92","lat":33.58150607,"lng":130.35272161,"geo_status":"db","era":"江戸末期／明治23増築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積150㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"40 ‐ 0137","desc":"市街地の旧道に面する町家。正面外壁を塗込めて各部屋列に格子をたてる。内部は三列構成の右列を土間とし、左列の座敷は増築で屋根を落棟とする。中の間は吹抜けに漆塗の高欄を飾り、座敷では銘木を多用した座敷飾を備える。商家の発展過程を示す上質な町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010899"},{"id":"00010900","register_sub_id":"101","register_pk":"201735","name":"伊佐家住宅土蔵","kana":"いさけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県福岡市早良区高取一丁目92","lat":33.58165124,"lng":130.35264485,"geo_status":"db","era":"明治36","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積36㎡","structure_material":"土蔵造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"40 ‐ 0138","desc":"主屋北側に、中庭を介して南北棟で建つ。桁行七・五メートル梁間四・七メートル、土蔵造、切妻造桟瓦葺。東面が戸口で板戸片引きとし、庇を付ける。外壁漆喰塗で鉢巻を廻らし、上部の南面と東面に漆喰塗で縁取りした縦長窓を穿つ。屋敷構えを引立てる土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010900"},{"id":"00011589","register_sub_id":"101","register_pk":"210396","name":"椛島家住宅蔵","kana":"かばしまけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県糸島市二丈田中字大塚101","lat":33.53654389,"lng":130.16983889,"geo_status":"db","era":"大正8年","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積23㎡、渡り廊下付","structure_material":"土蔵造2階建","registered":"2017.05.02(平成29.05.02)","register_no":"40 - 0142","desc":"主屋北西の仏間から渡り廊下を介して南北棟で建つ、土蔵造二階建、切妻造桟瓦葺である。花崗岩積の基礎上に建ち、外壁は腰を人造石洗出し仕上とし、隅部ではドイツ壁技法によりルスティカ風の隅石を表し、漆喰の鉢巻を廻らす。もと納戸蔵と伝える良質な土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011589"},{"id":"00011588","register_sub_id":"101","register_pk":"210395","name":"椛島家住宅庫院","kana":"かばしまけじゅうたくこいん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"福岡県","address":"福岡県糸島市二丈田中字大塚101","lat":33.53621889,"lng":130.17007111,"geo_status":"db","era":"明治後期／平成27年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積68㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"40 - 0141","desc":"敷地南西隅に南北棟で建つ。木造平屋建、入母屋造桟瓦葺で、西、北面に下屋を廻らし、西面は吹放ちとする。外壁漆喰塗で腰を竪板張とし、西面南寄りに出入口を開く。広い庇が特徴的な外観など、旧家の納屋としての構造や意匠をよく保ち、敷地景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011588"},{"id":"00011587","register_sub_id":"101","register_pk":"210394","name":"椛島家住宅主屋","kana":"かばしまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県糸島市二丈田中字大塚101","lat":33.53641306,"lng":130.17,"geo_status":"db","era":"明治30年頃／平成20年頃改修","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積264㎡","structure_material":"木造平屋一部2階建","registered":"2017.05.02(平成29.05.02)","register_no":"40 - 0140","desc":"敷地中央に南面する二階建。正面に出格子や大小の八角形の格子窓を配して独特な外観をもち、東寄りを土間とする。床上部は食違いの五室の西側に角屋を二列張出し、前列を奥座敷、後列を仏間などとし、造作も質が高い。当地方の近代大型住宅の特徴をよく示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011587"},{"id":"00011594","register_sub_id":"101","register_pk":"210401","name":"椛島家住宅庭門及び塀","kana":"かばしまけじゅうたくにわもんおよびうちべいにわもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県糸島市二丈田中字大塚101","lat":33.536275,"lng":130.16995611,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"庭門 木造、瓦葺、間口1.3m 塀 木造、瓦葺、総延長9.8m","structure_material":"庭門 木造","registered":"2017.05.02(平成29.05.02)","register_no":"40 - 0147","desc":"主屋正面から奥座敷前の主庭を囲むように廻り、主庭と表庭を画す門及び塀。門は腕木門、切妻造桟瓦葺で、欄間周囲を塗込めて主屋と意匠統一がなされる。塀は外側を竪板張として欄間を透かす。簡明かつ繊細な意匠をもち、庭内に落着いた風情を醸す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011594"},{"id":"00011593","register_sub_id":"101","register_pk":"210400","name":"椛島家住宅東門・北門及び塀","kana":"かばしまけじゅうたくひがしもん・きたもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県糸島市二丈田中字大塚101","lat":33.53639111,"lng":130.17010889,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"東門 木造、瓦葺、間口1.8m 北門 木造、瓦葺、間口2.0m 塀 木造、瓦葺、総延長32m","structure_material":"東門 木造","registered":"2017.05.02(平成29.05.02)","register_no":"40 - 0146","desc":"庫院北東隅から北にのびて敷地東辺を画す塀と、途中に開く東門、北端の北門。両門とも腕木門、切妻造桟瓦葺で板戸内開とする。塀は内外とも漆喰塗で、南寄りの前庭部は潜りと格子を設け、北寄りでは外側に簓子下見板を張る。庫院と調和が図られた意匠をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011593"},{"id":"00011591","register_sub_id":"101","register_pk":"210398","name":"椛島家住宅祠","kana":"かばしまけじゅうたくほこら","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"福岡県","address":"福岡県糸島市二丈田中字大塚101","lat":33.53652694,"lng":130.17006611,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、鉄板葺、建築面積0.42㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"40 - 0144","desc":"社の北東方で煉瓦積の基壇上に南北棟で建つ。桁行、梁間とも〇・六五メートル、切妻造鉄板葺、妻入である。井桁に組む土台に柱を立て、開口となる南面を格子戸両開きとし、他は竪板張とする。内部は縦長の玉石を祀る。社ととにも屋敷の鬼門を守る小祠である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011591"},{"id":"00011592","register_sub_id":"101","register_pk":"210399","name":"椛島家住宅南門及び塀","kana":"かばしまけじゅうたくみなみもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県糸島市二丈田中字大塚101","lat":33.536125,"lng":130.17000694,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"南門 木造、瓦葺、間口2.9m 塀 木造、瓦葺、総延長23m","structure_material":"南門 木造","registered":"2017.05.02(平成29.05.02)","register_no":"40 - 0145","desc":"主屋大戸口正面に構える南門と東西にのびる塀。南門は間口二・九メートルの薬医門、切妻造桟瓦葺。本柱を五平とし、冠木上に梁を三筋架け、軒桁、棟木とも舟肘木で受け、棟通り中央に蟇股を飾る。塀は腰板張で欄間を透かす。格式ある表構えを創る門塀である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011592"},{"id":"00011590","register_sub_id":"101","register_pk":"210397","name":"椛島家住宅社","kana":"かばしまけじゅうたくやしろ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"福岡県","address":"福岡県糸島市二丈田中字大塚101","lat":33.53649806,"lng":130.17005194,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積5.5㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"40 - 0143","desc":"主屋北東方に南北棟で建つ。切妻造桟瓦葺、妻入で、内部を前後に二分し、奥を内陣、前寄りを外陣とする。外陣は正面を格子引違、側面を窓として開放的に作り、内陣は竪板壁。両妻面は、柱上の三斗で妻虹梁を受けて蟇股を載せる。敷地景観を形成する社である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011590"},{"id":"00014974","register_sub_id":"101","register_pk":"519234","name":"河野家住宅（旧池本家住宅）主屋","kana":"かわのけじゅうたく（きゅういけもとけじゅうたく）おもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県北九州市八幡東区猪倉町66","lat":33.84729722,"lng":130.82211667,"geo_status":"db","era":"明治前期／昭和52年・平成31年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、茅葺(鉄板仮葺)、建築面積108㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"40 - 0220","desc":"槻田川上流の農村集落に位置する農家の主屋。平屋建入母屋造平入で茅葺(鉄板仮葺)の東西棟。西を土間、東を六間取とし、南東に床構え付き座敷を配し、南に縁を付す。三本溝の敷鴨居や簀子天井など古式を残す。大きな茅葺屋根が地域の歴史的景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014974"},{"id":"00002701","register_sub_id":"101","register_pk":"103691","name":"旧蔵内家住宅応接間棟","kana":"きゅうくらうちけじゅうたくおうせつまとう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"福岡県","address":"福岡県築上郡築上町大字上深野396","lat":33.6367,"lng":130.99463198,"geo_status":"db","era":"明治20","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積110㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"40 － 0020","desc":"東西棟の桟瓦葺・入母屋造で，周囲に銅板葺の下屋庇を廻し，内部は１５畳と１０畳の２室からなる。付書院や欄間の細工など，良材を用いた繊細な造形である。年代は主屋と同時期で，主屋と東北隅で繋がり，大玄関棟や茶室と雁行し，連続感のある構成をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002701"},{"id":"00002700","register_sub_id":"101","register_pk":"103690","name":"旧蔵内家住宅大玄関棟","kana":"きゅうくらうちけじゅうたくおおげんかんとう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"大正","pref":"福岡県","address":"福岡県築上郡築上町大字上深野396","lat":33.63658786,"lng":130.99475199,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積147㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"40 － 0019","desc":"主屋をはじめとする建築群の正面に建つ。戸袋に貼られた新聞より大正９年の建設と判明する。東面して建つ銅板葺の妻入建物で，屋根はＴ字型の大棟として東・南・北に妻飾を設け，その周囲にも一段低い屋根を架ける。全体として変化に富む外観を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002700"},{"id":"00002705","register_sub_id":"101","register_pk":"103695","name":"旧蔵内家住宅大広間棟","kana":"きゅうくらうちけじゅうたくおおひろまとう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"大正","pref":"福岡県","address":"福岡県築上郡築上町大字上深野396","lat":33.63696782,"lng":130.99441618,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積240㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"40 － 0024","desc":"座敷棟の北にある南北棟の長大な建物で，東に築かれた庭園に臨んで建ち，格調ある佇まいをみせる。屋根はＴ字型の大棟で三方に破風を設け，周囲に庇を廻す。１８畳が２室続く内部も広壮で座敷飾にも特色がある。棟札より棟梁は近郷山田村の中江九壽と判る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002705"},{"id":"00002709","register_sub_id":"101","register_pk":"103699","name":"旧蔵内家住宅倉","kana":"きゅうくらうちけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"福岡県","address":"福岡県築上郡築上町大字上深野396","lat":33.63660668,"lng":130.99413273,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積173㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"40 － 0028","desc":"屋敷南西の角地を画するように建ち，東面で米倉と接する。Ｌ字型平面とし，南面のほぼ中央に通用門を構え，内部を分けて農機具倉・左官倉・大工倉などに用いていた。屋根は桟瓦葺，真壁造で外廻りの腰を縦板張にする。大邸宅の屋敷構成を特色づける施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002709"},{"id":"00002708","register_sub_id":"101","register_pk":"103698","name":"旧蔵内家住宅米倉","kana":"きゅうくらうちけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"福岡県","address":"福岡県築上郡築上町大字上深野396","lat":33.63654372,"lng":130.99439829,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積88㎡","structure_material":"木造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"40 － 0027","desc":"主屋の南側にある米を収蔵していた土蔵で，主屋側に庇を設け，渡廊下で連絡していた。東西に細長い建物で，桟瓦葺の屋根は東妻を兜造風，西妻を切妻造とする。道路に面した南壁面は漆喰塗で腰を縦板張とするが，東妻は下見板張とし，存在感のある外観である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002708"},{"id":"00002704","register_sub_id":"101","register_pk":"103694","name":"旧蔵内家住宅座敷棟","kana":"きゅうくらうちけじゅうたくざしきとう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"大正","pref":"福岡県","address":"福岡県築上郡築上町大字上深野396","lat":33.63683475,"lng":130.99439357,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積138㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"40 － 0023","desc":"主屋の北西に接続する建物で，大広間棟などとともに，事業拡大を図った大正期に整えられた。東西棟・入母屋造・桟瓦葺で，周囲に一間幅の下屋庇をつける。内部は１０畳間２室で，主屋側の室に床の間や付書院を設け，数寄屋風の丁寧なつくりになっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002704"},{"id":"00002702","register_sub_id":"101","register_pk":"103692","name":"旧蔵内家住宅主屋","kana":"きゅうくらうちけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県築上郡築上町大字上深野396","lat":33.63668486,"lng":130.99449827,"geo_status":"db","era":"明治20","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造2階建、瓦葺、建築面積256㎡","structure_material":"木造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"40 － 0021","desc":"東を正面とした桁行８間半，梁間４間の総２階建，南北棟・桟瓦葺・入母屋造の屋根を上げた建物で，大邸宅の中心に相応しい雄大さを備えている。西面には低い屋根を架けて，１階に居間など内向きの部屋を設けている。竣工写真から建築年代が判明する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002702"},{"id":"00002706","register_sub_id":"101","register_pk":"103696","name":"旧蔵内家住宅炊事場棟","kana":"きゅうくらうちけじゅうたくすいじばとう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"大正","pref":"福岡県","address":"福岡県築上郡築上町大字上深野396","lat":33.63670863,"lng":130.99430799,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積178㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"40 － 0025","desc":"主屋西面の南側で接続する。炊事場・食堂・台所・浴室・便所・井戸など，居住のサービス機能を備えた部分である。真壁造で端整なつくりになるが，東西棟・入母屋造・桟瓦葺の大屋根を架け，入母屋造の一段低い下屋を各方向に付けた賑やかな外観としている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002706"},{"id":"00002703","register_sub_id":"101","register_pk":"103693","name":"旧蔵内家住宅茶室","kana":"きゅうくらうちけじゅうたくちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県築上郡築上町大字上深野396","lat":33.6367979,"lng":130.99458644,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積47㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"40 － 0022","desc":"主屋北側に位置し，応接棟の北西隅と巧みに接続している。入母屋造で，周囲に下屋庇を廻し，その西面には入母屋破風を設ける。現在銅板葺であるが当初は檜皮葺であった。茶室は８畳で，床の間の落掛に竹を用い，全体を木割の細い数寄屋風意匠で纏めている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002703"},{"id":"00002710","register_sub_id":"101","register_pk":"103700","name":"旧蔵内家住宅中門","kana":"きゅうくらうちけじゅうたくちゅうもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県築上郡築上町大字上深野396","lat":33.63660075,"lng":130.99490113,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋建、銅板葺、間口1.8m","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"40 － 0029","desc":"大玄関棟の北東にあり，アプローチ空間と屋敷北側に築かれた庭園を連絡する門で，古写真から大正１０年の建築と判明する。桁行１間，梁間１間，入母屋造・銅板葺の小規模な門であるが，自然の丸柱，丸太の桁や垂木など，数寄屋風の整った造形である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002710"},{"id":"00002711","register_sub_id":"101","register_pk":"103701","name":"旧蔵内家住宅便所","kana":"きゅうくらうちけじゅうたくべんじょ","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"大正","pref":"福岡県","address":"福岡県築上郡築上町大字上深野396","lat":33.63644287,"lng":130.99472623,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積5.7㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"40 － 0030","desc":"屋敷南側に開かれた入口脇にあり，中門と同じ頃の建築と推定される。寄棟造・桟瓦葺の小規模な建物であるが，腰高で石造風のコンクリート基礎上に，自然の丸柱を立て，桁や垂木も丸太とし，墨壁に丸窓を設けるなど，よく数寄屋風の意匠で纏められている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002711"},{"id":"00002707","register_sub_id":"101","register_pk":"103697","name":"旧蔵内家住宅宝蔵","kana":"きゅうくらうちけじゅうたくほうぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県築上郡築上町大字上深野396","lat":33.63683246,"lng":130.99423546,"geo_status":"db","era":"明治20頃","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造2階建、瓦葺、建築面積116㎡","structure_material":"木造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"40 － 0026","desc":"座敷棟と炊事場の後方，屋敷西面中央に建つ収蔵施設。桁行１０間の壮大な規模を有し，南北に細長い切妻造・桟瓦葺・２階建の土蔵で，内部の南北に２箇所の階段を設ける。壁面は丁寧な仕上の漆喰塗とし，小庇付窓を数多く配するなど，特色あるつくりである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002707"},{"id":"00014697","register_sub_id":"101","register_pk":"515239","name":"旧柴田家住宅主屋","kana":"きゅうしばたけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県福岡市東区馬出五丁目397","lat":33.61277222,"lng":130.42105278,"geo_status":"db","era":"大正前期／昭和22年・同42年頃・平成15年改修","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造2階建、瓦葺、建築面積104㎡","structure_material":"木造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"40 - 0214","desc":"唐津街道に西面する曲物業を営んだ商家。二階建切妻造平入桟瓦葺で、軒は出桁造とし、正面二階に手摺を付す。内部一階は前土間とし、南に二室を並べ東北に台所棟、東南に便所棟が附属。二階は南東室を主座敷とする。筥崎宮周辺の歴史的景観を形成する町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014697"},{"id":"00008604","register_sub_id":"101","register_pk":"135000","name":"旧林田春次郎家住宅迎賓館","kana":"きゅうはやしだはるじろうけじゅうたくげいひんかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福岡県","address":"福岡県田川市新町3330-1他","lat":33.64486587,"lng":130.81073982,"geo_status":"db","era":"昭和9年／昭和後期改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造2階建、銅板葺、建築面積124㎡","structure_material":"木造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"40 － 0068","desc":"主屋の北方に位置する木造二階建。入母屋造銅板葺の緩やかな屋根になる。一階に小部屋、二階に大広間と次の間を配し、香春岳を望む東面に広縁を設ける。大広間北端にトコと棚を構え、その東北には瀟洒な角部屋を造る。銘木を用い、優れた和風意匠が印象的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008604"},{"id":"00008603","register_sub_id":"101","register_pk":"134999","name":"旧林田春次郎家住宅本屋","kana":"きゅうはやしだはるじろうけじゅうたくほんや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"福岡県","address":"福岡県田川市新町3330-1他","lat":33.64467974,"lng":130.81067778,"geo_status":"db","era":"大正3年／昭和後期改修","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積210㎡","structure_material":"木造平屋一部2階建","registered":"2011.01.26(平成23.01.26)","register_no":"40 － 0067","desc":"市街地の高台に占める敷地中央に東面して建つ。東西棟の入母屋造妻入桟瓦葺、木造二階建と、その北面に付く入母屋造平屋建からなる。建築面積二一〇平方メートル。平屋部分は前後二列の六間取で、前列北室にトコを構える。変化のある外観を構成する近代の住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008603"},{"id":"00011586","register_sub_id":"101","register_pk":"210515","name":"旧吉原家住宅通用門及び煉瓦塀","kana":"きゅうよしはらけじゅうたくつうようもんおよびれんがべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"福岡県","address":"福岡県大川市大字小保字中ノ船津136-17他","lat":33.206703,"lng":130.369938,"geo_status":"db","era":"江戸末期／大正末期増築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"通用門 木造、瓦葺、間口4.6m 煉瓦塀 煉瓦造、瓦葺、総延長31m","structure_material":"通用門 木造","registered":"2017.05.02(平成29.05.02)","register_no":"40-0139","desc":"重要文化財旧吉原家住宅の敷地南面東隅の通用門とその東西に連続する煉瓦塀。西煉瓦塀は途中に附指定の御成門を挟む。通用門は切妻造桟瓦葺の棟門で片引戸二枚を建て込む珍しい形式である。煉瓦塀は灰褐色の鉱滓煉瓦積で桟瓦葺の屋根を載せ正面景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011586"},{"id":"00004087","register_sub_id":"101","register_pk":"105077","name":"楠森河北家住宅米蔵・器蔵","kana":"くすもりかわきたけじゅうたくこめぐら・うつわぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"福岡県","address":"福岡県うきは市浮羽町山北2056","lat":33.32992371,"lng":130.80768951,"geo_status":"db","era":"文化9／安政4増築","year":1812,"year_source":"db","year_min":1812,"year_max":1812,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積45㎡","structure_material":"土蔵造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"40 － 0037","desc":"南北棟の切妻造，桟瓦葺，２階建の土蔵で，外壁は漆喰塗，腰を縦板張とする。北半分の米蔵は棟木に文化９年の墨書，南半分の器蔵は柱に安政４年の墨書があり，器蔵が増築されて現状になった。窓及び庇のつくりや位置などの違いに建築時期の差が現れている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004087"},{"id":"00004084","register_sub_id":"101","register_pk":"105074","name":"楠森河北家住宅材木小屋","kana":"くすもりかわきたけじゅうたくざいもくごや","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"福岡県","address":"福岡県うきは市浮羽町山北2056","lat":33.3300677,"lng":130.80824065,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積95㎡","structure_material":"土蔵造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"40 － 0034","desc":"桁行約１６ｍの土蔵造で，西側に秤蔵が接続する。屋根は東西棟の切妻造，桟瓦葺で，南面に戸口を２箇所設け，庇を付ける。外壁は漆喰塗だが，内部は東西に分かれ，西側は２階建になるが，東側は吹き抜けの広大な１室とする。屋敷内で最も大きい収納施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004084"},{"id":"00004082","register_sub_id":"101","register_pk":"105072","name":"楠森河北家住宅座敷","kana":"くすもりかわきたけじゅうたくざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"福岡県","address":"福岡県うきは市浮羽町山北2056","lat":33.32974992,"lng":130.80779651,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積83㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"40 － 0032","desc":"主屋の南西方に接続して建つ離れ座敷。木造平屋建，３室からなるＬ字型平面で，屋根は南北棟の入母屋造で下屋を廻し，南面東側は寄棟造屋根を突出する。全体に繊細な数寄屋風のつくりで，軒下の小壁に軒丸瓦を嵌め込んで飾るなど，要所に趣向を凝らしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004082"},{"id":"00004081","register_sub_id":"101","register_pk":"105071","name":"楠森河北家住宅主屋","kana":"くすもりかわきたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県うきは市浮羽町山北2056","lat":33.32988284,"lng":130.80787359,"geo_status":"db","era":"明治14","year":1881,"year_source":"db","year_min":1881,"year_max":1881,"year_label":null,"structure":"木造2階建、瓦葺、建築面積254㎡","structure_material":"木造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"40 － 0031","desc":"東面して建つ妻入の木造２階建。屋根は，東面入母屋造，西面切妻造，桟瓦葺で，各面には高さの異なる下屋を廻し，南面や西面に角屋を突出するなど，複雑な平面に対応した変化ある外観をつくる。上層民家に相応しい雄大な規模と，格式のある構成を備えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004081"},{"id":"00004083","register_sub_id":"101","register_pk":"105073","name":"楠森河北家住宅新座敷","kana":"くすもりかわきたけじゅうたくしんざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"福岡県","address":"福岡県うきは市浮羽町山北2056","lat":33.32970402,"lng":130.80793351,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋建、瓦葺、建築面積71㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"40 － 0033","desc":"主屋南面の東に廊下で結ばれている接客用の座敷。木造平屋建，入母屋造，桟瓦葺で，下屋を廻す。内部は１間半の大床を備えた１２畳半の１室で，周囲に縁側を設け，開放的な扱いとする。良材を用いた丁寧なつくりになり，壁や欄間などの造作も手が込んでいる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004083"},{"id":"00004086","register_sub_id":"101","register_pk":"105076","name":"楠森河北家住宅炭部屋","kana":"くすもりかわきたけじゅうたくすみべや","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"江戸","pref":"福岡県","address":"福岡県うきは市浮羽町山北2056","lat":33.329998,"lng":130.807755,"geo_status":"db","era":"万延2頃","year":1861,"year_source":"db","year_min":1861,"year_max":1861,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積68㎡","structure_material":"土蔵造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"40 － 0036","desc":"主屋の北西方に離れて建ち，西で米蔵と接する。木造２階建，東西棟の切妻造，桟瓦葺で，南面には戸口２箇所を設け，下屋庇をつける。外壁は漆喰塗で，１階の腰を縦板張とし，２階に虫籠窓などを設ける。１階３室，２階に居室を設けた重厚なつくりの付属施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004086"},{"id":"00004085","register_sub_id":"101","register_pk":"105075","name":"楠森河北家住宅秤蔵","kana":"くすもりかわきたけじゅうたくはかりぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県うきは市浮羽町山北2056","lat":33.33007,"lng":130.80798062,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積45㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"40 － 0035","desc":"桁行約７ｍの木造平屋建，切妻造，桟瓦葺で，材木小屋の西妻面に接続して建つ。床材に万延２年の墨書があるが，家相図より明治後期に現在地に移動し，改造されたと考えられる。現在は車庫等になっているが，屋敷構成の変遷を知る上で欠かせない存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004085"},{"id":"00004088","register_sub_id":"101","register_pk":"105078","name":"楠森河北家住宅味噌部屋","kana":"くすもりかわきたけじゅうたくみそべや","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"福岡県","address":"福岡県うきは市浮羽町山北2056","lat":33.32982071,"lng":130.80771141,"geo_status":"db","era":"明治前期／大正期増築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造平屋建、瓦葺、建築面積23㎡","structure_material":"土蔵造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"40 － 0038","desc":"主屋の西方にある。木造平屋建，南北棟の切妻造，桟瓦葺で，東面に戸口を設け，東と西の各面に虫籠窓を設ける。外壁は軒裏まで塗込めた荒壁仕上で，腰は縦板張とする。南妻面の下屋は大正期の増築である。主屋北西方の裏庭空間の構成要素のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004088"},{"id":"00012658","register_sub_id":"101","register_pk":"367952","name":"倉員家住宅主屋","kana":"くらかずけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県八女市上陽町北川内字坂口山1016","lat":33.236687,"lng":130.657715,"geo_status":"geocoded","era":"明治18年／昭和42年頃改修","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積300㎡","structure_material":"木造2階一部平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"40 － 0155","desc":"旧北川内村中心部にある地主の居宅。主屋は敷地中央に南面して建つ。入母屋造桟瓦葺の二階建で、正面東半を張出して矩折れに屋根をかけ、四周に下屋を廻す。内部は西に土間、東に2列3室を配し、表に座敷を並べる。良材を多用した上質なつくりの和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012658"},{"id":"00012660","register_sub_id":"101","register_pk":"367954","name":"倉員家住宅土蔵","kana":"くらかずけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県八女市上陽町北川内字坂口山1016","lat":33.236687,"lng":130.657715,"geo_status":"geocoded","era":"明治24年","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積51㎡","structure_material":"土蔵造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"40 － 0157","desc":"敷地南面の石垣上に北面して建つ。土蔵造二階建、東西棟の切妻造で、正面東寄りに庇付の戸口を設け、石段を築く。外壁は漆喰塗で腰壁が縦板張、内部は一階が土間、二階が板敷で、和小屋を組む。主屋前庭を囲んで建つ附属建物で、伝統的な農家の構成を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012660"},{"id":"00012661","register_sub_id":"101","register_pk":"367955","name":"倉員家住宅納屋","kana":"くらかずけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県八女市上陽町北川内字坂口山1016","lat":33.236687,"lng":130.657715,"geo_status":"geocoded","era":"明治9年","year":1876,"year_source":"db","year_min":1876,"year_max":1876,"year_label":null,"structure":"木造2階建、瓦葺、建築面積51㎡","structure_material":"木造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"40 － 0158","desc":"敷地南面の土蔵前方に北面して建つ。切妻造桟瓦葺の二階建で、正面に下屋を通し、下屋上に縦格子窓を設ける。外壁は漆喰塗で腰壁が縦板張、内部は一面土間で前面を開放とし、二階に物置を設ける。土蔵と同じく伝統的な農家の構成を示す附属建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012661"},{"id":"00012659","register_sub_id":"101","register_pk":"367953","name":"倉員家住宅離れ","kana":"くらかずけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県八女市上陽町北川内字坂口山1016","lat":33.236687,"lng":130.657715,"geo_status":"geocoded","era":"明治42年／昭和63年改修","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積97㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"40 － 0156","desc":"敷地北面に南面して建つ。土蔵造平屋建、入母屋造桟瓦葺で、正面西半を角屋で主屋と接続する。床組を敷地背面の石垣上から張出してつくり、広い床下空間を確保する。内部は三室を並べ、東端に座敷を設ける。上層農家の暮らしの一端を伝える附属建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012659"},{"id":"00013665","register_sub_id":"101","register_pk":"505028","name":"古賀家住宅主屋","kana":"こがけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"福岡県","address":"福岡県大牟田市谷町1-12他","lat":33.032075,"lng":130.44885,"geo_status":"db","era":"昭和28年","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積184㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"40 － 0181","desc":"大牟田市の中心街に位置する。玄関の南脇に応接棟がつき東に洋間棟、座敷棟、離れ棟をそれぞれ別棟で雁行して配する。いずれも入母屋造桟瓦葺。座敷、離れは和風で統一する一方、応接間は洋風で設えるなど、比較的大規模な和洋を併置した戦後の住宅の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013665"},{"id":"00013766","register_sub_id":"101","register_pk":"505329","name":"杣人の家","kana":"そまびとのいえ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"福岡県","address":"福岡県八女市矢部村北矢部字松尾9932","lat":33.14759722,"lng":130.84008611,"geo_status":"db","era":"明治後期／昭和35年増築改修、同61年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積219㎡","structure_material":"木造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"40 － 185","desc":"八女市の山間部の敷地に南面して建つ。木造二階建入母屋造平入桟瓦葺。四周に下屋を廻し、北東に平屋建の座敷棟を突出させる。西に土間、東に三列六室を並べて上部は全て大引天井とし、二階は広い一室の板間とする。軸組に欅等の良材を用いた明治後期の民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013766"},{"id":"00009558","register_sub_id":"101","register_pk":"194351","name":"多田家住宅石塀","kana":"ただけじゅうたくいしべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"福岡県","address":"福岡県朝倉郡筑前町森山字耳取417-1","lat":33.45238388,"lng":130.62221941,"geo_status":"db","era":"昭和8年頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"石造、総延長48m","structure_material":"石造","registered":"2013.03.29(平成25.03.29)","register_no":"40 － 0101","desc":"敷地南辺の西寄り、表門から東西に折れ曲がりにのびる。自然石の石垣上に布石を伏せ、江戸切り仕上げの積石を積み上げる。積石は、表門両側では五段積み、通り沿いでは三段積とし、総延長四七・八メートルを測る。旧家らしい風格ある屋敷構えをみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009558"}];
